insert into public.training_questions
  (module, card_key, locale, question, options, correct_index, explanation, hint, legal_ref)
values
  ('tacho', 'tacho.d1', 'fi', 'Kuinka pitkään saat enintään ajaa kuorma-autoa vuorokaudessa?', '["8 h","9 h, enintään 10 h korkeintaan kahdesti viikossa","10 h joka päivä","11 h"]'::jsonb, 1, 'Päivittäinen ajoaika on 9 h. Sen voi pidentää 10 tuntiin kahdesti viikossa.', 'Etsi vastaus, jossa on sekä perusraja että poikkeus.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'en', 'What is the maximum daily driving time for a truck?', '["8 h","9 h, up to 10 h no more than twice a week","10 h every day","11 h"]'::jsonb, 1, 'Daily driving time is 9 h. It may be extended to 10 h twice a week.', 'Look for the answer with both the basic limit and the exception.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'et', 'Kui kaua tohid veokit ööpäevas maksimaalselt juhtida?', '["8 h","9 h, kuni 10 h mitte rohkem kui kaks korda nädalas","10 h iga päev","11 h"]'::jsonb, 1, 'Ööpäevane sõiduaeg on 9 h. Kaks korda nädalas võib seda pikendada 10 tunnini.', 'Otsi vastust, kus on nii põhipiirang kui ka erand.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'ru', 'Сколько максимум можно вести грузовик за сутки?', '["8 ч","9 ч, до 10 ч не более двух раз в неделю","10 ч каждый день","11 ч"]'::jsonb, 1, 'Суточное вождение — 9 ч. Дважды за неделю его можно продлить до 10 ч.', 'Ищи ответ, где есть и базовый лимит, и исключение.', '561/2006, ст. 6(1)'),
  ('tacho', 'tacho.d1', 'sv', 'Hur länge får du som mest köra lastbil per dygn?', '["8 h","9 h, upp till 10 h högst två gånger i veckan","10 h varje dag","11 h"]'::jsonb, 1, 'Den dagliga körtiden är 9 h. Två gånger i veckan får den förlängas till 10 h.', 'Leta efter svaret som har både grundgränsen och undantaget.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'lv', 'Cik ilgi diennaktī drīksti vadīt kravas auto maksimāli?', '["8 h","9 h, līdz 10 h ne vairāk kā divreiz nedēļā","10 h katru dienu","11 h"]'::jsonb, 1, 'Ikdienas braukšanas laiks ir 9 h. Divreiz nedēļā to drīkst pagarināt līdz 10 h.', 'Meklē atbildi, kurā ir gan pamatlimits, gan izņēmums.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'lt', 'Kiek daugiausia valandų per parą gali vairuoti sunkvežimį?', '["8 val.","9 val., iki 10 val. ne dažniau kaip du kartus per savaitę","10 val. kasdien","11 val."]'::jsonb, 1, 'Kasdienis vairavimo laikas – 9 val. Du kartus per savaitę jį galima pratęsti iki 10 val.', 'Ieškok atsakymo, kuriame yra ir pagrindinė riba, ir išimtis.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'pl', 'Ile maksymalnie możesz prowadzić ciężarówkę w ciągu doby?', '["8 godz.","9 godz., do 10 godz. nie częściej niż dwa razy w tygodniu","10 godz. codziennie","11 godz."]'::jsonb, 1, 'Dzienny czas prowadzenia to 9 godz. Dwa razy w tygodniu można go wydłużyć do 10 godz.', 'Szukaj odpowiedzi, w której jest i limit podstawowy, i wyjątek.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'nb', 'Hvor lenge kan du maksimalt kjøre lastebil per døgn?', '["8 t","9 t, opptil 10 t høyst to ganger i uken","10 t hver dag","11 t"]'::jsonb, 1, 'Daglig kjøretid er 9 t. To ganger i uken kan den forlenges til 10 t.', 'Se etter svaret som har både grunngrensen og unntaket.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d1', 'da', 'Hvor længe må du højst køre lastbil pr. døgn?', '["8 t","9 t, op til 10 t højst to gange om ugen","10 t hver dag","11 t"]'::jsonb, 1, 'Den daglige køretid er 9 t. To gange om ugen må den forlænges til 10 t.', 'Kig efter svaret med både grundgrænsen og undtagelsen.', '561/2006, art. 6(1)'),
  ('tacho', 'tacho.d2', 'fi', 'Mikä on ajoajan enimmäismäärä yhdellä viikolla?', '["48 h","56 h","60 h","90 h"]'::jsonb, 1, 'Viikossa saa ajaa enintään 56 h.', 'Se on vähemmän kuin 9 h × 6 päivää.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'en', 'What is the driving limit for one week?', '["48 h","56 h","60 h","90 h"]'::jsonb, 1, 'No more than 56 h of driving per week.', 'It is less than 9 h × 6 days.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'et', 'Milline on sõiduaja piirang ühe nädala kohta?', '["48 h","56 h","60 h","90 h"]'::jsonb, 1, 'Nädalas tohib sõita kõige rohkem 56 h.', 'See on vähem kui 9 h × 6 päeva.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'ru', 'Какой лимит вождения за одну неделю?', '["48 ч","56 ч","60 ч","90 ч"]'::jsonb, 1, 'За неделю — не более 56 ч вождения.', 'Это меньше, чем 9 ч × 6 дней.', '561/2006, ст. 6(2)'),
  ('tacho', 'tacho.d2', 'sv', 'Vad är gränsen för körtid under en vecka?', '["48 h","56 h","60 h","90 h"]'::jsonb, 1, 'Högst 56 h körning per vecka.', 'Det är mindre än 9 h × 6 dagar.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'lv', 'Kāds ir braukšanas laika limits vienai nedēļai?', '["48 h","56 h","60 h","90 h"]'::jsonb, 1, 'Nedēļā drīkst braukt ne vairāk kā 56 h.', 'Tas ir mazāk nekā 9 h × 6 dienas.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'lt', 'Koks yra vairavimo laiko limitas per vieną savaitę?', '["48 val.","56 val.","60 val.","90 val."]'::jsonb, 1, 'Per savaitę – ne daugiau kaip 56 val. vairavimo.', 'Tai mažiau nei 9 val. × 6 dienos.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'pl', 'Jaki jest limit czasu prowadzenia w ciągu jednego tygodnia?', '["48 godz.","56 godz.","60 godz.","90 godz."]'::jsonb, 1, 'W tygodniu nie więcej niż 56 godz. prowadzenia.', 'To mniej niż 9 godz. × 6 dni.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'nb', 'Hva er grensen for kjøretid i løpet av én uke?', '["48 t","56 t","60 t","90 t"]'::jsonb, 1, 'Høyst 56 t kjøring per uke.', 'Det er mindre enn 9 t × 6 dager.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d2', 'da', 'Hvad er grænsen for køretid i løbet af én uge?', '["48 t","56 t","60 t","90 t"]'::jsonb, 1, 'Højst 56 t kørsel pr. uge.', 'Det er mindre end 9 t × 6 dage.', '561/2006, art. 6(2)'),
  ('tacho', 'tacho.d3', 'fi', 'Kuinka paljon saat ajaa yhteensä kahden peräkkäisen viikon aikana?', '["90 h","100 h","112 h","120 h"]'::jsonb, 0, 'Minä tahansa kahtena peräkkäisenä viikkona enintään 90 h. Siksi kahta 56 tunnin viikkoa peräkkäin ei voi ajaa.', 'Kahta täyttä viikkoa ei voi ajaa peräkkäin.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'en', 'How much may you drive in total over two consecutive weeks?', '["90 h","100 h","112 h","120 h"]'::jsonb, 0, 'No more than 90 h in any two consecutive weeks. So two 56-hour weeks in a row are impossible.', 'You can''t drive two maximum weeks in a row.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'et', 'Kui palju tohib kokku sõita kahe järjestikuse nädala jooksul?', '["90 h","100 h","112 h","120 h"]'::jsonb, 0, 'Mis tahes kahe järjestikuse nädala jooksul mitte rohkem kui 90 h. Seega kaks 56-tunnist nädalat järjest ei ole võimalik.', 'Kahte maksimaalset nädalat järjest sõita ei saa.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'ru', 'Сколько можно водить за две недели подряд в сумме?', '["90 ч","100 ч","112 ч","120 ч"]'::jsonb, 0, 'За любые две недели подряд — не более 90 ч. Поэтому две недели по 56 ч подряд невозможны.', 'Две недели по максимуму не проехать.', '561/2006, ст. 6(3)'),
  ('tacho', 'tacho.d3', 'sv', 'Hur mycket får du köra sammanlagt under två veckor i följd?', '["90 h","100 h","112 h","120 h"]'::jsonb, 0, 'Högst 90 h under två på varandra följande veckor. Två veckor med 56 h i rad går alltså inte.', 'Två maxveckor i rad går inte.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'lv', 'Cik kopā drīkst braukt divās nedēļās pēc kārtas?', '["90 h","100 h","112 h","120 h"]'::jsonb, 0, 'Jebkurās divās nedēļās pēc kārtas — ne vairāk kā 90 h. Tāpēc divas nedēļas pa 56 h pēc kārtas nav iespējamas.', 'Divas maksimālās nedēļas pēc kārtas nobraukt nevar.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'lt', 'Kiek iš viso gali vairuoti per dvi savaites iš eilės?', '["90 val.","100 val.","112 val.","120 val."]'::jsonb, 0, 'Per bet kurias dvi savaites iš eilės – ne daugiau kaip 90 val. Todėl dvi savaitės po 56 val. iš eilės neįmanomos.', 'Dviejų maksimalių savaičių iš eilės neišvažiuosi.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'pl', 'Ile łącznie możesz prowadzić w ciągu dwóch kolejnych tygodni?', '["90 godz.","100 godz.","112 godz.","120 godz."]'::jsonb, 0, 'W dowolnych dwóch kolejnych tygodniach nie więcej niż 90 godz. Dlatego dwa tygodnie po 56 godz. z rzędu są niemożliwe.', 'Dwóch maksymalnych tygodni z rzędu nie przejedziesz.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'nb', 'Hvor mye kan du kjøre til sammen over to uker på rad?', '["90 t","100 t","112 t","120 t"]'::jsonb, 0, 'Høyst 90 t i løpet av to uker på rad. To uker med 56 t etter hverandre er derfor umulig.', 'To maksuker på rad går ikke.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.d3', 'da', 'Hvor meget må du køre i alt over to uger i træk?', '["90 t","100 t","112 t","120 t"]'::jsonb, 0, 'Højst 90 t i to på hinanden følgende uger. To uger med 56 t i træk er derfor umuligt.', 'To maksuger i træk kan ikke lade sig gøre.', '561/2006, art. 6(3)'),
  ('tacho', 'tacho.b1', 'fi', 'Olet ajanut 4 h 30 min ilman taukoa. Mitä seuraavaksi?', '["Tauko 30 min","Tauko 45 min","Tauko 15 min","Voi ajaa 5 tuntiin asti"]'::jsonb, 1, '4 h 30 min ajon jälkeen pidetään vähintään 45 min tauko, jos sitä ei ole jaettu aiemmin.', 'Tämä on piirturin tunnetuin sääntö.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'en', 'You have driven 4 h 30 min without a break. What next?', '["30 min break","45 min break","15 min break","You can drive up to 5 h"]'::jsonb, 1, 'After 4 h 30 min of driving, take a break of at least 45 min unless it was split earlier.', 'This is the best-known tachograph rule.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'et', 'Oled sõitnud 4 h 30 min ilma pausita. Mis edasi?', '["Paus 30 min","Paus 45 min","Paus 15 min","Võib sõita kuni 5 h"]'::jsonb, 1, 'Pärast 4 h 30 min sõitu tuleb teha vähemalt 45-minutiline paus, kui seda pole varem osadeks jagatud.', 'See on sõidumeerikuga seotud kõige tuntum reegel.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'ru', 'Проехал 4 ч 30 мин без перерыва. Что дальше?', '["Перерыв 30 мин","Перерыв 45 мин","Перерыв 15 мин","Можно ехать до 5 ч"]'::jsonb, 1, 'После 4 ч 30 мин вождения — перерыв не менее 45 мин, если он не был разделён раньше.', 'Это самое известное правило тахографа.', '561/2006, ст. 7'),
  ('tacho', 'tacho.b1', 'sv', 'Du har kört 4 h 30 min utan rast. Vad gäller nu?', '["Rast 30 min","Rast 45 min","Rast 15 min","Du får köra upp till 5 h"]'::jsonb, 1, 'Efter 4 h 30 min körning ska du ta minst 45 min rast, om den inte redan delats upp tidigare.', 'Det här är färdskrivarens mest kända regel.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'lv', 'Esi nobraucis 4 h 30 min bez pārtraukuma. Kas tālāk?', '["Pārtraukums 30 min","Pārtraukums 45 min","Pārtraukums 15 min","Var braukt līdz 5 h"]'::jsonb, 1, 'Pēc 4 h 30 min braukšanas jāieņem vismaz 45 min pārtraukums, ja tas nav sadalīts agrāk.', 'Tas ir pazīstamākais tahogrāfa noteikums.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'lt', 'Vairavai 4 val. 30 min. be pertraukos. Kas toliau?', '["Pertrauka 30 min.","Pertrauka 45 min.","Pertrauka 15 min.","Galima važiuoti iki 5 val."]'::jsonb, 1, 'Po 4 val. 30 min. vairavimo – ne trumpesnė kaip 45 min. pertrauka, jei ji nebuvo padalyta anksčiau.', 'Tai žinomiausia tachografo taisyklė.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'pl', 'Jedziesz 4 godz. 30 min bez przerwy. Co dalej?', '["Przerwa 30 min","Przerwa 45 min","Przerwa 15 min","Można jechać do 5 godz."]'::jsonb, 1, 'Po 4 godz. 30 min jazdy – przerwa co najmniej 45 min, jeśli nie została wcześniej podzielona.', 'To najbardziej znana zasada tachografu.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'nb', 'Du har kjørt 4 t 30 min uten pause. Hva nå?', '["Pause 30 min","Pause 45 min","Pause 15 min","Du kan kjøre til 5 t"]'::jsonb, 1, 'Etter 4 t 30 min kjøring skal du ta minst 45 min pause, med mindre den er delt opp tidligere.', 'Dette er fartsskriverens mest kjente regel.', '561/2006, art. 7'),
  ('tacho', 'tacho.b1', 'da', 'Du har kørt 4 t 30 min uden pause. Hvad nu?', '["Pause 30 min","Pause 45 min","Pause 15 min","Du må køre op til 5 t"]'::jsonb, 1, 'Efter 4 t 30 min kørsel skal du holde mindst 45 min pause, medmindre den er delt op tidligere.', 'Det er fartskriverens mest kendte regel.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'fi', 'Voiko 45 minuutin tauon jakaa osiin 30 + 15 min?', '["Kyllä, missä järjestyksessä tahansa","Ei, vain 15 ja sitten 30","Kyllä, mutta vain lautalla","Ei, jakaminen on kokonaan kielletty"]'::jsonb, 1, 'Tauon voi jakaa vain näin: ensin vähintään 15 min, sitten vähintään 30 min. Järjestystä 30 + 15 ei hyväksytä.', 'Järjestyksellä on väliä.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'en', 'Can the 45-minute break be split as 30 + 15 minutes?', '["Yes, in any order","No, only 15 then 30","Yes, but only on a ferry","No, it can''t be split at all"]'::jsonb, 1, 'The break can only be split like this: first at least 15 min, then at least 30 min. The order 30 + 15 does not count.', 'The order matters.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'et', 'Kas 45-minutilise pausi võib jagada 30 + 15 minutiks?', '["Jah, mis tahes järjekorras","Ei, ainult 15 ja siis 30","Jah, aga ainult praamil","Ei, jagada ei tohi üldse"]'::jsonb, 1, 'Pausi võib jagada ainult nii: kõigepealt vähemalt 15 min, siis vähemalt 30 min. Järjekorda 30 + 15 ei arvestata.', 'Järjekord on oluline.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'ru', 'Можно ли разделить 45-минутный перерыв как 30 + 15 минут?', '["Да, в любом порядке","Нет, только 15, затем 30","Да, но только на пароме","Нет, делить нельзя вообще"]'::jsonb, 1, 'Перерыв делится только так: сначала не менее 15 мин, потом не менее 30 мин. Порядок 30 + 15 не засчитывается.', 'Порядок имеет значение.', '561/2006, ст. 7'),
  ('tacho', 'tacho.b2', 'sv', 'Får rasten på 45 minuter delas upp som 30 + 15 minuter?', '["Ja, i valfri ordning","Nej, bara 15 och sedan 30","Ja, men bara på färja","Nej, den får inte delas alls"]'::jsonb, 1, 'Rasten får bara delas så här: först minst 15 min, sedan minst 30 min. Ordningen 30 + 15 räknas inte.', 'Ordningen spelar roll.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'lv', 'Vai 45 minūšu pārtraukumu drīkst sadalīt kā 30 + 15 minūtes?', '["Jā, jebkādā secībā","Nē, tikai 15, tad 30","Jā, bet tikai uz prāmja","Nē, dalīt nedrīkst vispār"]'::jsonb, 1, 'Pārtraukumu var sadalīt tikai tā: vispirms vismaz 15 min, tad vismaz 30 min. Secība 30 + 15 netiek ieskaitīta.', 'Secībai ir nozīme.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'lt', 'Ar galima 45 min. pertrauką padalyti į 30 + 15 min.?', '["Taip, bet kokia tvarka","Ne, tik 15, po to 30","Taip, bet tik kelte","Ne, dalyti apskritai negalima"]'::jsonb, 1, 'Pertrauką galima padalyti tik taip: pirmiausia ne trumpesnė kaip 15 min., po to ne trumpesnė kaip 30 min. Tvarka 30 + 15 neįskaitoma.', 'Tvarka svarbi.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'pl', 'Czy 45-minutową przerwę można podzielić na 30 + 15 minut?', '["Tak, w dowolnej kolejności","Nie, tylko 15, potem 30","Tak, ale tylko na promie","Nie, w ogóle nie można jej dzielić"]'::jsonb, 1, 'Przerwę można podzielić tylko tak: najpierw co najmniej 15 min, potem co najmniej 30 min. Kolejność 30 + 15 się nie liczy.', 'Kolejność ma znaczenie.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'nb', 'Kan pausen på 45 minutter deles opp som 30 + 15 minutter?', '["Ja, i hvilken som helst rekkefølge","Nei, bare 15 og så 30","Ja, men bare på ferje","Nei, den kan ikke deles i det hele tatt"]'::jsonb, 1, 'Pausen kan bare deles slik: først minst 15 min, så minst 30 min. Rekkefølgen 30 + 15 teller ikke.', 'Rekkefølgen betyr noe.', '561/2006, art. 7'),
  ('tacho', 'tacho.b2', 'da', 'Må pausen på 45 minutter deles op som 30 + 15 minutter?', '["Ja, i vilkårlig rækkefølge","Nej, kun 15 og derefter 30","Ja, men kun på færge","Nej, den må slet ikke deles"]'::jsonb, 1, 'Pausen må kun deles sådan: først mindst 15 min, derefter mindst 30 min. Rækkefølgen 30 + 15 tæller ikke.', 'Rækkefølgen betyder noget.', '561/2006, art. 7'),
  ('tacho', 'tacho.b3', 'fi', 'Lastaus kesti 45 minuuttia. Lasketaanko se tauoksi?', '["Kyllä, jos et ollut ratissa","Kyllä, jos auto seisoi paikallaan","Ei, se on ”muuta työtä”","Vain jos joku muu lastasi"]'::jsonb, 2, 'Lastaus, purku ja ajoneuvon tarkastus ovat ”muuta työtä” (ristikkäiset vasarat). Tauko on vain lepoa.', 'Tauko on aikaa, jolloin olet vapaa kaikesta työstä.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'en', 'Loading took 45 minutes. Does it count as a break?', '["Yes, if you weren''t at the wheel","Yes, if the truck was standing still","No, it is “other work”","Only if someone else did the loading"]'::jsonb, 2, 'Loading, unloading and vehicle checks are “other work” (crossed hammers symbol). A break is rest only.', 'A break is time when you are free from any work.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'et', 'Laadimine kestis 45 minutit. Kas seda arvestatakse pausiks?', '["Jah, kui sa ei olnud roolis","Jah, kui auto seisis paigal","Ei, see on „muu töö“","Ainult siis, kui laadis keegi teine"]'::jsonb, 2, 'Laadimine, mahalaadimine ja sõiduki ülevaatus on „muu töö“ (ristatud haamrite sümbol). Paus on ainult puhkus.', 'Paus on aeg, mil oled vaba igasugusest tööst.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'ru', 'Погрузка заняла 45 минут. Это засчитывается как перерыв?', '["Да, если не за рулём","Да, если стоял на месте","Нет, это «другая работа»","Только если погрузку делал не ты"]'::jsonb, 2, 'Погрузка, разгрузка, осмотр машины — это «другая работа» (символ скрещённых молотков). Перерыв — только отдых.', 'Перерыв — это время, когда ты свободен от любой работы.', '561/2006, ст. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'sv', 'Lastningen tog 45 minuter. Räknas det som rast?', '["Ja, om du inte satt vid ratten","Ja, om bilen stod still","Nej, det är ”annat arbete”","Bara om någon annan lastade"]'::jsonb, 2, 'Lastning, lossning och kontroll av fordonet är ”annat arbete” (symbolen med korsade hammare). Rast är bara vila.', 'Rast är tid då du är fri från allt arbete.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'lv', 'Iekraušana ilga 45 minūtes. Vai to ieskaita kā pārtraukumu?', '["Jā, ja nebiji pie stūres","Jā, ja auto stāvēja uz vietas","Nē, tas ir “cits darbs”","Tikai tad, ja iekrāva kāds cits"]'::jsonb, 2, 'Iekraušana, izkraušana, transportlīdzekļa apskate ir “cits darbs” (sakrustotu āmuru simbols). Pārtraukums ir tikai atpūta.', 'Pārtraukums ir laiks, kad esi brīvs no jebkāda darba.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'lt', 'Pakrovimas truko 45 minutes. Ar tai įskaitoma kaip pertrauka?', '["Taip, jei nebuvai prie vairo","Taip, jei stovėjai vietoje","Ne, tai „kitas darbas“","Tik jei krovė ne tu"]'::jsonb, 2, 'Pakrovimas, iškrovimas, transporto priemonės apžiūra – tai „kitas darbas“ (sukryžiuotų plaktukų simbolis). Pertrauka – tik poilsis.', 'Pertrauka – tai laikas, kai esi laisvas nuo bet kokio darbo.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'pl', 'Załadunek trwał 45 minut. Czy liczy się jako przerwa?', '["Tak, jeśli nie siedziałeś za kierownicą","Tak, jeśli auto stało w miejscu","Nie, to „inna praca”","Tylko jeśli ładował ktoś inny"]'::jsonb, 2, 'Załadunek, rozładunek i kontrola pojazdu to „inna praca” (symbol skrzyżowanych młotków). Przerwa to wyłącznie odpoczynek.', 'Przerwa to czas, gdy jesteś wolny od wszelkiej pracy.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'nb', 'Lastingen tok 45 minutter. Teller det som pause?', '["Ja, hvis du ikke satt bak rattet","Ja, hvis bilen sto stille","Nei, det er «annet arbeid»","Bare hvis noen andre lastet"]'::jsonb, 2, 'Lasting, lossing og kontroll av kjøretøyet er «annet arbeid» (symbolet med kryssede hammere). Pause er bare hvile.', 'Pause er tid da du er fri fra alt arbeid.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.b3', 'da', 'Læsningen tog 45 minutter. Tæller det som pause?', '["Ja, hvis du ikke sad bag rattet","Ja, hvis bilen holdt stille","Nej, det er »andet arbejde«","Kun hvis en anden læssede"]'::jsonb, 2, 'Læsning, losning og kontrol af køretøjet er »andet arbejde« (symbolet med krydsede hamre). Pause er kun hvile.', 'Pause er tid, hvor du er fri for alt arbejde.', '561/2006, art. 4; 2002/15/EC'),
  ('tacho', 'tacho.r1', 'fi', 'Kuinka pitkä on säännöllinen vuorokausilepo?', '["9 h","10 h","11 h, voidaan jakaa 3 + 9","12 h jakamatta"]'::jsonb, 2, 'Säännöllinen vuorokausilepo on 11 h. Sen voi jakaa: ensin vähintään 3 h, sitten vähintään 9 h (yhteensä 12 h).', 'Jaettuna kokonaisaika pitenee.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'en', 'How long is a regular daily rest?', '["9 h","10 h","11 h, can be split 3 + 9","12 h without splitting"]'::jsonb, 2, 'A regular daily rest is 11 h. It can be split: first at least 3 h, then at least 9 h (12 h in total).', 'Splitting makes the total longer.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'et', 'Kui pikk on tavaline igapäevane puhkeaeg?', '["9 h","10 h","11 h, võib jagada 3 + 9","12 h jagamata"]'::jsonb, 2, 'Regulaarne igapäevane puhkeaeg on 11 h. Seda võib jagada: kõigepealt vähemalt 3 h, siis vähemalt 9 h (kokku 12 h).', 'Jagamisel kogu aeg pikeneb.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'ru', 'Сколько длится обычный ежедневный отдых?', '["9 ч","10 ч","11 ч, можно разделить 3 + 9","12 ч без разделения"]'::jsonb, 2, 'Регулярный ежедневный отдых — 11 ч. Можно разделить: сначала не менее 3 ч, затем не менее 9 ч (итого 12 ч).', 'При разделении общее время увеличивается.', '561/2006, ст. 4(g), 8'),
  ('tacho', 'tacho.r1', 'sv', 'Hur lång är en normal dygnsvila?', '["9 h","10 h","11 h, kan delas 3 + 9","12 h utan uppdelning"]'::jsonb, 2, 'Normal dygnsvila är 11 h. Den kan delas: först minst 3 h, sedan minst 9 h (totalt 12 h).', 'Vid uppdelning blir den totala tiden längre.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'lv', 'Cik ilga ir parastā ikdienas atpūta?', '["9 h","10 h","11 h, var sadalīt 3 + 9","12 h bez sadalīšanas"]'::jsonb, 2, 'Regulārā ikdienas atpūta ir 11 h. To var sadalīt: vispirms vismaz 3 h, tad vismaz 9 h (kopā 12 h).', 'Sadalot kopējais laiks palielinās.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'lt', 'Kiek trunka įprastas kasdienis poilsis?', '["9 val.","10 val.","11 val., galima padalyti 3 + 9","12 val. nedalijant"]'::jsonb, 2, 'Įprastas kasdienis poilsis – 11 val. Jį galima padalyti: pirmiausia ne mažiau kaip 3 val., po to ne mažiau kaip 9 val. (iš viso 12 val.).', 'Padalijus bendras laikas pailgėja.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'pl', 'Ile trwa regularny dzienny odpoczynek?', '["9 godz.","10 godz.","11 godz., można podzielić 3 + 9","12 godz. bez dzielenia"]'::jsonb, 2, 'Regularny dzienny okres odpoczynku to 11 godz. Można go podzielić: najpierw co najmniej 3 godz., potem co najmniej 9 godz. (razem 12 godz.).', 'Przy podziale łączny czas się wydłuża.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'nb', 'Hvor lang er vanlig døgnhvil?', '["9 t","10 t","11 t, kan deles 3 + 9","12 t uten oppdeling"]'::jsonb, 2, 'Vanlig døgnhvil er 11 t. Den kan deles: først minst 3 t, så minst 9 t (totalt 12 t).', 'Ved oppdeling blir den totale tiden lengre.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r1', 'da', 'Hvor lang er et almindeligt dagligt hvil?', '["9 t","10 t","11 t, kan deles 3 + 9","12 t uden opdeling"]'::jsonb, 2, 'Et regelmæssigt dagligt hvil er 11 t. Det kan deles: først mindst 3 t, derefter mindst 9 t (i alt 12 t).', 'Ved opdeling bliver den samlede tid længere.', '561/2006, art. 4(g), 8'),
  ('tacho', 'tacho.r2', 'fi', 'Kuinka usein saat pitää lyhennetyn 9 tunnin vuorokausilevon?', '["Joka päivä","Enintään 3 kertaa kahden viikkolevon välillä","Enintään 2 kertaa viikossa","Vain kansainvälisillä keikoilla"]'::jsonb, 1, 'Lyhennetyn vuorokausilevon (9–11 h) voi pitää enintään kolme kertaa kahden viikkolevon välillä.', 'Onko luku sama kuin ajoajan pidennyksissä? Ei, se on suurempi.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'en', 'How often may you take a reduced 9-hour daily rest?', '["Every day","No more than 3 times between two weekly rests","No more than twice a week","Only on international trips"]'::jsonb, 1, 'A reduced daily rest (9 to 11 h) may be taken no more than three times between two weekly rest periods.', 'Is it the same number as the driving extensions? No, it''s higher.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'et', 'Kui tihti tohib võtta lühendatud 9-tunnise igapäevase puhkeaja?', '["Iga päev","Mitte rohkem kui 3 korda kahe iganädalase puhkeaja vahel","Mitte rohkem kui 2 korda nädalas","Ainult rahvusvahelistel vedudel"]'::jsonb, 1, 'Lühendatud igapäevast puhkeaega (9–11 h) võib võtta kõige rohkem kolm korda kahe iganädalase puhkeaja vahel.', 'Kas arv on sama mis sõiduaja pikendustel? Ei, suurem.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'ru', 'Как часто можно брать сокращённый ежедневный отдых 9 ч?', '["Каждый день","Не более 3 раз между двумя еженедельными отдыхами","Не более 2 раз в неделю","Только в международных рейсах"]'::jsonb, 1, 'Сокращённый ежедневный отдых (от 9 до 11 ч) — не более трёх раз между двумя еженедельными отдыхами.', 'Число совпадает с количеством продлений? Нет, больше.', '561/2006, ст. 8(4)'),
  ('tacho', 'tacho.r2', 'sv', 'Hur ofta får du ta reducerad dygnsvila på 9 h?', '["Varje dag","Högst 3 gånger mellan två veckovilor","Högst 2 gånger i veckan","Bara på internationella körningar"]'::jsonb, 1, 'Reducerad dygnsvila (9–11 h) får tas högst tre gånger mellan två veckovilor.', 'Samma antal som förlängningarna av körtiden? Nej, fler.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'lv', 'Cik bieži drīkst izmantot saīsinātu 9 h ikdienas atpūtu?', '["Katru dienu","Ne vairāk kā 3 reizes starp divām iknedēļas atpūtām","Ne vairāk kā 2 reizes nedēļā","Tikai starptautiskajos reisos"]'::jsonb, 1, 'Saīsināto ikdienas atpūtu (9–11 h) drīkst izmantot ne vairāk kā trīs reizes starp diviem iknedēļas atpūtas laikposmiem.', 'Vai skaitlis sakrīt ar pagarinājumu skaitu? Nē, lielāks.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'lt', 'Kaip dažnai galima naudoti sutrumpintą 9 val. kasdienį poilsį?', '["Kasdien","Ne daugiau kaip 3 kartus tarp dviejų savaitinių poilsių","Ne daugiau kaip 2 kartus per savaitę","Tik tarptautiniuose reisuose"]'::jsonb, 1, 'Sutrumpintas kasdienis poilsis (nuo 9 iki 11 val.) – ne daugiau kaip tris kartus tarp dviejų savaitinio poilsio laikotarpių.', 'Ar skaičius sutampa su pratęsimų skaičiumi? Ne, didesnis.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'pl', 'Jak często można korzystać ze skróconego 9-godzinnego odpoczynku dziennego?', '["Codziennie","Nie więcej niż 3 razy między dwoma odpoczynkami tygodniowymi","Nie więcej niż 2 razy w tygodniu","Tylko w przewozach międzynarodowych"]'::jsonb, 1, 'Skrócony dzienny okres odpoczynku (od 9 do 11 godz.) – nie więcej niż trzy razy między dwoma tygodniowymi okresami odpoczynku.', 'Czy liczba jest taka sama jak przedłużeń jazdy? Nie, większa.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'nb', 'Hvor ofte kan du ta redusert døgnhvil på 9 t?', '["Hver dag","Høyst 3 ganger mellom to ukehviler","Høyst 2 ganger i uken","Bare på internasjonale turer"]'::jsonb, 1, 'Redusert døgnhvil (9–11 t) kan tas høyst tre ganger mellom to ukehviler.', 'Samme antall som forlengelsene av kjøretiden? Nei, flere.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.r2', 'da', 'Hvor ofte må du holde reduceret dagligt hvil på 9 t?', '["Hver dag","Højst 3 gange mellem to ugentlige hvil","Højst 2 gange om ugen","Kun på internationale ture"]'::jsonb, 1, 'Reduceret dagligt hvil (9–11 t) må holdes højst tre gange mellem to ugentlige hvileperioder.', 'Samme antal som forlængelserne af køretiden? Nej, flere.', '561/2006, art. 8(4)'),
  ('tacho', 'tacho.w1', 'fi', 'Saako säännöllisen viikkolevon (45 h) pitää ohjaamossa?', '["Kyllä, jos on makuupaikka","Kyllä, vartioidulla pysäköintialueella","Ei, tarvitaan asianmukainen majoitus","Kyllä, jos kuljettaja suostuu"]'::jsonb, 2, 'Säännöllistä viikkolepoa eikä korvauksena pidettävää yli 45 tunnin lepoa saa pitää ohjaamossa. Majoituksen järjestää ja maksaa työnantaja.', 'Tämä on yksi liikkuvuuspaketin tärkeimmistä muutoksista.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'en', 'May you spend a regular weekly rest (45 h) in the cab?', '["Yes, if there is a sleeping berth","Yes, in a secure parking area","No, suitable accommodation is required","Yes, if the driver agrees"]'::jsonb, 2, 'A regular weekly rest, and any weekly rest over 45 h taken as compensation, may not be spent in the cab. The employer arranges and pays for the accommodation.', 'This is one of the key changes of the Mobility Package.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'et', 'Kas regulaarset iganädalast puhkeaega (45 h) tohib veeta kabiinis?', '["Jah, kui on magamiskoht","Jah, valvega parklas","Ei, vaja on sobivat majutust","Jah, kui juht on nõus"]'::jsonb, 2, 'Regulaarset iganädalast puhkeaega ega üle 45 h hüvitavat puhkeaega ei tohi veeta kabiinis. Majutuse korraldab ja maksab tööandja.', 'See on liikuvuspaketi üks peamisi muudatusi.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'ru', 'Можно ли проводить регулярный еженедельный отдых (45 ч) в кабине?', '["Да, если есть спальное место","Да, на охраняемой стоянке","Нет, нужно жильё с подходящими условиями","Да, если водитель согласен"]'::jsonb, 2, 'Регулярный еженедельный отдых и отдых 45 ч+ в качестве компенсации в кабине проводить нельзя. Жильё организует и оплачивает работодатель.', 'Это одно из ключевых изменений Пакета мобильности.', '561/2006, ст. 8(8a)'),
  ('tacho', 'tacho.w1', 'sv', 'Får du ta normal veckovila (45 h) i hytten?', '["Ja, om det finns sovplats","Ja, på en bevakad parkering","Nej, det krävs lämpligt boende","Ja, om föraren går med på det"]'::jsonb, 2, 'Normal veckovila och vila på mer än 45 h som kompensation får inte tas i hytten. Arbetsgivaren ordnar och betalar boendet.', 'Det här är en av de viktigaste ändringarna i mobilitetspaketet.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'lv', 'Vai regulāro iknedēļas atpūtu (45 h) drīkst pavadīt kabīnē?', '["Jā, ja ir guļvieta","Jā, apsargātā stāvvietā","Nē, vajadzīga piemērota naktsmītne","Jā, ja vadītājs piekrīt"]'::jsonb, 2, 'Regulāro iknedēļas atpūtu un atpūtu virs 45 h kā kompensāciju kabīnē pavadīt nedrīkst. Naktsmītni organizē un apmaksā darba devējs.', 'Tā ir viena no galvenajām Mobilitātes paketes izmaiņām.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'lt', 'Ar galima reguliarųjį savaitinį poilsį (45 val.) praleisti kabinoje?', '["Taip, jei yra miegamoji vieta","Taip, saugomoje aikštelėje","Ne, reikia tinkamo apgyvendinimo","Taip, jei vairuotojas sutinka"]'::jsonb, 2, 'Reguliariojo savaitinio poilsio ir ilgesnio nei 45 val. poilsio kaip kompensacijos kabinoje praleisti negalima. Apgyvendinimą organizuoja ir apmoka darbdavys.', 'Tai vienas svarbiausių Mobilumo paketo pakeitimų.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'pl', 'Czy regularny tygodniowy odpoczynek (45 godz.) można spędzić w kabinie?', '["Tak, jeśli jest miejsce do spania","Tak, na strzeżonym parkingu","Nie, potrzebne jest odpowiednie zakwaterowanie","Tak, jeśli kierowca się zgadza"]'::jsonb, 2, 'Regularnego tygodniowego odpoczynku ani odpoczynku powyżej 45 godz. jako rekompensaty nie wolno spędzać w kabinie. Zakwaterowanie organizuje i opłaca pracodawca.', 'To jedna z kluczowych zmian Pakietu Mobilności.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'nb', 'Kan du ta vanlig ukehvil (45 t) i førerhuset?', '["Ja, hvis det er soveplass","Ja, på en bevoktet parkeringsplass","Nei, det kreves egnet overnatting","Ja, hvis sjåføren samtykker"]'::jsonb, 2, 'Vanlig ukehvil og hvil over 45 t som kompensasjon kan ikke tas i førerhuset. Arbeidsgiveren ordner og betaler overnattingen.', 'Dette er en av de viktigste endringene i mobilitetspakken.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w1', 'da', 'Må du holde regelmæssigt ugentligt hvil (45 t) i førerhuset?', '["Ja, hvis der er sovekøje","Ja, på en bevogtet parkeringsplads","Nej, der kræves egnet indkvartering","Ja, hvis chaufføren accepterer det"]'::jsonb, 2, 'Regelmæssigt ugentligt hvil og hvil over 45 t som kompensation må ikke holdes i førerhuset. Arbejdsgiveren arrangerer og betaler indkvarteringen.', 'Det er en af de vigtigste ændringer i mobilitetspakken.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w2', 'fi', 'Lyhennetyn viikkolevon vähimmäispituus on…', '["9 h","24 h","36 h","45 h"]'::jsonb, 1, 'Lyhennetty viikkolepo on vähintään 24 h. Puuttuva aika korvataan yhtäjaksoisesti ennen kyseistä viikkoa seuraavan kolmannen viikon loppua.', 'Tasan yksi vuorokausi.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'en', 'The minimum reduced weekly rest is…', '["9 h","24 h","36 h","45 h"]'::jsonb, 1, 'A reduced weekly rest is at least 24 h. The missing time must be compensated in one block before the end of the third week following it.', 'Exactly one day.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'et', 'Lühendatud iganädalase puhkeaja miinimum on…', '["9 h","24 h","36 h","45 h"]'::jsonb, 1, 'Lühendatud iganädalane puhkeaeg on vähemalt 24 h. Puuduv aeg tuleb hüvitada ühe tervikuna enne sellele järgneva kolmanda nädala lõppu.', 'Täpselt üks ööpäev.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'ru', 'Минимальный сокращённый еженедельный отдых — это…', '["9 ч","24 ч","36 ч","45 ч"]'::jsonb, 1, 'Сокращённый еженедельный отдых — не менее 24 ч. Недостающее время нужно компенсировать одним блоком до конца третьей недели после неё.', 'Ровно одни сутки.', '561/2006, ст. 8(6)'),
  ('tacho', 'tacho.w2', 'sv', 'Kortaste reducerade veckovila är…', '["9 h","24 h","36 h","45 h"]'::jsonb, 1, 'Reducerad veckovila är minst 24 h. Den saknade tiden ska kompenseras i ett block före utgången av den tredje veckan därefter.', 'Exakt ett dygn.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'lv', 'Minimālā saīsinātā iknedēļas atpūta ir…', '["9 h","24 h","36 h","45 h"]'::jsonb, 1, 'Saīsinātā iknedēļas atpūta ir vismaz 24 h. Trūkstošais laiks jākompensē vienā blokā līdz trešās nedēļas beigām pēc tās.', 'Tieši viena diennakts.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'lt', 'Mažiausias sutrumpintas savaitinis poilsis yra…', '["9 val.","24 val.","36 val.","45 val."]'::jsonb, 1, 'Sutrumpintas savaitinis poilsis – ne mažiau kaip 24 val. Trūkstamą laiką reikia kompensuoti vienu kartu iki trečios po jo einančios savaitės pabaigos.', 'Lygiai viena para.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'pl', 'Minimalny skrócony tygodniowy odpoczynek to…', '["9 godz.","24 godz.","36 godz.","45 godz."]'::jsonb, 1, 'Skrócony tygodniowy okres odpoczynku to co najmniej 24 godz. Brakujący czas trzeba zrekompensować w jednym bloku przed końcem trzeciego tygodnia następującego po nim.', 'Dokładnie jedna doba.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'nb', 'Minste reduserte ukehvil er…', '["9 t","24 t","36 t","45 t"]'::jsonb, 1, 'Redusert ukehvil er minst 24 t. Den manglende tiden må kompenseres samlet før utløpet av den tredje uken etterpå.', 'Nøyaktig ett døgn.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w2', 'da', 'Det mindste reducerede ugentlige hvil er…', '["9 t","24 t","36 t","45 t"]'::jsonb, 1, 'Reduceret ugentligt hvil er mindst 24 t. Den manglende tid skal kompenseres samlet inden udgangen af den tredje uge derefter.', 'Præcis ét døgn.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'fi', 'Milloin viikkolevon on alettava?', '["56 ajotunnin jälkeen","Viimeistään kuuden 24 tunnin jakson jälkeen edellisestä","Sunnuntaina","7 päivää töihin lähdön jälkeen"]'::jsonb, 1, 'Viikkolepo alkaa viimeistään kuuden 24 tunnin jakson päättyessä edellisen viikkolevon jälkeen.', 'Kuusi vuorokautta työtä on enimmäismäärä.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'en', 'When must a weekly rest start?', '["After 56 h of driving","No later than 6 periods of 24 h after the previous one","On Sunday","7 days after starting work"]'::jsonb, 1, 'A weekly rest starts no later than at the end of six 24-hour periods from the end of the previous weekly rest.', 'Six days of work is the maximum.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'et', 'Millal peab iganädalane puhkeaeg algama?', '["Pärast 56 h sõitu","Hiljemalt kuue 24-tunnise perioodi järel eelmisest","Pühapäeval","7 päeva pärast tööle asumist"]'::jsonb, 1, 'Iganädalane puhkeaeg algab hiljemalt kuue 24-tunnise perioodi lõpus pärast eelmise iganädalase puhkeaja lõppu.', 'Kuus ööpäeva tööd on maksimum.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'ru', 'Когда должен начаться еженедельный отдых?', '["После 56 ч вождения","Не позже 6 периодов по 24 ч после предыдущего","В воскресенье","Через 7 дней после выхода на работу"]'::jsonb, 1, 'Еженедельный отдых начинается не позднее конца шести 24-часовых периодов после окончания предыдущего.', 'Шесть суток работы — максимум.', '561/2006, ст. 8(6)'),
  ('tacho', 'tacho.w3', 'sv', 'När måste veckovilan börja?', '["Efter 56 h körning","Senast efter 6 perioder om 24 h från den förra","På söndag","7 dagar efter att du börjat jobba"]'::jsonb, 1, 'Veckovilan börjar senast vid slutet av sex 24-timmarsperioder efter slutet av den föregående veckovilan.', 'Sex dygns arbete är max.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'lv', 'Kad jāsākas iknedēļas atpūtai?', '["Pēc 56 h braukšanas","Ne vēlāk kā pēc 6 periodiem pa 24 h kopš iepriekšējās","Svētdienā","7 dienas pēc darba sākšanas"]'::jsonb, 1, 'Iknedēļas atpūta sākas ne vēlāk kā sešu 24 stundu periodu beigās pēc iepriekšējās iknedēļas atpūtas beigām.', 'Sešas diennaktis darba — maksimums.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'lt', 'Kada turi prasidėti savaitinis poilsis?', '["Po 56 val. vairavimo","Ne vėliau kaip po 6 laikotarpių po 24 val. nuo ankstesnio","Sekmadienį","Praėjus 7 dienoms nuo darbo pradžios"]'::jsonb, 1, 'Savaitinis poilsis prasideda ne vėliau kaip po šešių 24 val. laikotarpių nuo ankstesnio savaitinio poilsio pabaigos.', 'Šešios paros darbo – daugiausia.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'pl', 'Kiedy musi rozpocząć się tygodniowy odpoczynek?', '["Po 56 godz. jazdy","Nie później niż po 6 okresach 24-godzinnych od poprzedniego","W niedzielę","7 dni po rozpoczęciu pracy"]'::jsonb, 1, 'Tygodniowy okres odpoczynku rozpoczyna się nie później niż z końcem sześciu 24-godzinnych okresów od zakończenia poprzedniego.', 'Sześć dób pracy – maksimum.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'nb', 'Når må ukehvilen begynne?', '["Etter 56 t kjøring","Senest etter 6 perioder på 24 t fra den forrige","På søndag","7 dager etter at du begynte å jobbe"]'::jsonb, 1, 'Ukehvilen begynner senest ved utløpet av seks 24-timersperioder etter slutten av forrige ukehvil.', 'Seks døgn arbeid er maks.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w3', 'da', 'Hvornår skal det ugentlige hvil begynde?', '["Efter 56 t kørsel","Senest efter 6 perioder på 24 t fra det forrige","Om søndagen","7 dage efter at du startede på arbejde"]'::jsonb, 1, 'Det ugentlige hvil begynder senest ved udgangen af seks 24-timersperioder efter afslutningen af det forrige ugentlige hvil.', 'Seks døgns arbejde er maks.', '561/2006, art. 8(6)'),
  ('tacho', 'tacho.w4', 'fi', 'Kuinka usein kansainvälisillä keikoilla ajavan kuljettajan on päästävä kotiin tai toimipaikalle?', '["2 viikon välein","4 viikon välein","6 viikon välein","Kerran neljännesvuodessa"]'::jsonb, 1, 'Työnantaja järjestää kuljettajan paluun toimipaikalle tai asuinpaikkaansa jokaisen neljän peräkkäisen viikon aikana.', 'Suunnilleen kerran kuussa.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'en', 'How often must a driver on international trips be able to return home or to base?', '["Every 2 weeks","Every 4 weeks","Every 6 weeks","Once a quarter"]'::jsonb, 1, 'The employer arranges for the driver to return to the operational centre or place of residence within each period of 4 consecutive weeks.', 'Roughly once a month.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'et', 'Kui tihti peab rahvusvahelistel vedudel sõitev juht saama naasta koju või baasi?', '["Iga 2 nädala järel","Iga 4 nädala järel","Iga 6 nädala järel","Kord kvartalis"]'::jsonb, 1, 'Tööandja korraldab juhi naasmise tegevuskeskusesse või elukohta iga nelja järjestikuse nädala jooksul.', 'Umbes kord kuus.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'ru', 'Как часто водитель в международных рейсах должен иметь возможность вернуться домой или на базу?', '["Раз в 2 недели","Раз в 4 недели","Раз в 6 недель","Раз в квартал"]'::jsonb, 1, 'Работодатель организует возвращение водителя на базу или по месту жительства в течение каждых 4 недель подряд.', 'Примерно раз в месяц.', '561/2006, ст. 8(8a)'),
  ('tacho', 'tacho.w4', 'sv', 'Hur ofta ska en förare på internationella körningar kunna åka hem eller till basen?', '["Varannan vecka","Var fjärde vecka","Var sjätte vecka","En gång per kvartal"]'::jsonb, 1, 'Arbetsgivaren ordnar så att föraren kan återvända till driftscentralen eller bostaden inom varje period om fyra veckor i följd.', 'Ungefär en gång i månaden.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'lv', 'Cik bieži starptautiskos reisos braucošam vadītājam jāvar atgriezties mājās vai bāzē?', '["Reizi 2 nedēļās","Reizi 4 nedēļās","Reizi 6 nedēļās","Reizi ceturksnī"]'::jsonb, 1, 'Darba devējs organizē vadītāja atgriešanos bāzē vai dzīvesvietā katru četru secīgu nedēļu laikā.', 'Aptuveni reizi mēnesī.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'lt', 'Kaip dažnai tarptautiniuose reisuose dirbantis vairuotojas turi turėti galimybę grįžti namo ar į bazę?', '["Kas 2 savaites","Kas 4 savaites","Kas 6 savaites","Kartą per ketvirtį"]'::jsonb, 1, 'Darbdavys organizuoja vairuotojo grįžimą į bazę arba gyvenamąją vietą per kiekvieną 4 iš eilės einančių savaičių laikotarpį.', 'Maždaug kartą per mėnesį.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'pl', 'Jak często kierowca w przewozach międzynarodowych musi mieć możliwość powrotu do domu lub bazy?', '["Co 2 tygodnie","Co 4 tygodnie","Co 6 tygodni","Raz na kwartał"]'::jsonb, 1, 'Pracodawca organizuje powrót kierowcy do bazy lub miejsca zamieszkania w każdym okresie 4 kolejnych tygodni.', 'Mniej więcej raz w miesiącu.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'nb', 'Hvor ofte skal en sjåfør på internasjonale turer kunne reise hjem eller til basen?', '["Annenhver uke","Hver fjerde uke","Hver sjette uke","Én gang i kvartalet"]'::jsonb, 1, 'Arbeidsgiveren sørger for at sjåføren kan returnere til driftssenteret eller bostedet innen hver periode på fire uker på rad.', 'Omtrent én gang i måneden.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.w4', 'da', 'Hvor ofte skal en chauffør på internationale ture kunne komme hjem eller til basen?', '["Hver anden uge","Hver fjerde uge","Hver sjette uge","Én gang i kvartalet"]'::jsonb, 1, 'Arbejdsgiveren sørger for, at chaufføren kan vende tilbage til driftscentret eller bopælen inden for hver periode på fire uger i træk.', 'Cirka én gang om måneden.', '561/2006, art. 8(8a)'),
  ('tacho', 'tacho.c1', 'fi', 'Tienvarsitarkastus. Miltä ajalta merkinnät on esitettävä?', '["Kuluva päivä ja 28 edellistä","Kuluva päivä ja 56 edellistä","Vain kuluva viikko","Viimeiset 90 päivää"]'::jsonb, 1, '31.12.2024 alkaen kuljettaja esittää merkinnät kuluvalta päivältä ja 56 edelliseltä päivältä.', 'Ennen se oli 28 — nyt kaksinkertainen.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'en', 'Roadside check. For what period must you show records?', '["Current day and previous 28","Current day and previous 56","Only the current week","The last 90 days"]'::jsonb, 1, 'Since 31.12.2024 the driver must produce records for the current day and the previous 56 days.', 'It used to be 28 — now it''s double.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'et', 'Kontroll teel. Millise perioodi kohta tuleb andmed esitada?', '["Jooksev päev ja 28 eelmist","Jooksev päev ja 56 eelmist","Ainult jooksev nädal","Viimased 90 päeva"]'::jsonb, 1, 'Alates 31.12.2024 esitab juht andmed jooksva päeva ja sellele eelnenud 56 päeva kohta.', 'Varem oli 28 — nüüd kaks korda rohkem.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'ru', 'Проверка на дороге. За какой период нужно показать записи?', '["Текущий день и 28 предыдущих","Текущий день и 56 предыдущих","Только текущую неделю","Последние 90 дней"]'::jsonb, 1, 'С 31.12.2024 водитель предъявляет записи за текущий день и 56 предыдущих дней.', 'Раньше было 28 — теперь вдвое больше.', '165/2014, ст. 36 (ред. 2020/1054)'),
  ('tacho', 'tacho.c1', 'sv', 'Vägkontroll. För vilken period ska du visa registreringar?', '["Innevarande dag och 28 föregående","Innevarande dag och 56 föregående","Bara innevarande vecka","De senaste 90 dagarna"]'::jsonb, 1, 'Sedan 31.12.2024 ska föraren visa registreringar för innevarande dag och de 56 föregående dagarna.', 'Förut var det 28 — nu dubbelt så många.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'lv', 'Pārbaude uz ceļa. Par kādu periodu jāuzrāda ieraksti?', '["Pašreizējā diena un 28 iepriekšējās","Pašreizējā diena un 56 iepriekšējās","Tikai pašreizējā nedēļa","Pēdējās 90 dienas"]'::jsonb, 1, 'Kopš 31.12.2024 vadītājs uzrāda ierakstus par pašreizējo dienu un 56 iepriekšējām dienām.', 'Agrāk bija 28 — tagad divreiz vairāk.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'lt', 'Patikrinimas kelyje. Už kokį laikotarpį reikia parodyti įrašus?', '["Einamoji diena ir 28 ankstesnės","Einamoji diena ir 56 ankstesnės","Tik einamoji savaitė","Paskutinės 90 dienų"]'::jsonb, 1, 'Nuo 2024-12-31 vairuotojas pateikia įrašus už einamąją dieną ir 56 ankstesnes dienas.', 'Anksčiau buvo 28 – dabar dvigubai daugiau.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'pl', 'Kontrola drogowa. Za jaki okres trzeba okazać zapisy?', '["Bieżący dzień i 28 poprzednich","Bieżący dzień i 56 poprzednich","Tylko bieżący tydzień","Ostatnie 90 dni"]'::jsonb, 1, 'Od 31.12.2024 kierowca okazuje zapisy za bieżący dzień i 56 poprzednich dni.', 'Wcześniej było 28 – teraz dwa razy więcej.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'nb', 'Veikontroll. For hvilken periode må du vise registreringer?', '["Inneværende dag og 28 foregående","Inneværende dag og 56 foregående","Bare inneværende uke","De siste 90 dagene"]'::jsonb, 1, 'Fra 31.12.2024 skal sjåføren vise registreringer for inneværende dag og de 56 foregående dagene.', 'Før var det 28 — nå dobbelt så mange.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c1', 'da', 'Vejsidekontrol. For hvilken periode skal du vise registreringer?', '["Den aktuelle dag og de 28 foregående","Den aktuelle dag og de 56 foregående","Kun den aktuelle uge","De sidste 90 dage"]'::jsonb, 1, 'Siden 31.12.2024 skal chaufføren fremvise registreringer for den aktuelle dag og de 56 foregående dage.', 'Før var det 28 — nu dobbelt så mange.', '165/2014, art. 36 (2020/1054)'),
  ('tacho', 'tacho.c2', 'fi', 'Kuinka usein kuljettajakortin tiedot on purettava?', '["7 päivän välein","28 päivän välein","90 päivän välein","Kerran vuodessa"]'::jsonb, 1, 'Kuljettajakortin tiedot puretaan vähintään 28 päivän välein. Ajoneuvoyksikön tiedot vähintään 90 päivän välein.', 'Kortin määräaika on lyhyempi kuin ajoneuvoyksikön.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'en', 'How often must the driver card data be downloaded?', '["Every 7 days","Every 28 days","Every 90 days","Once a year"]'::jsonb, 1, 'Driver card data is downloaded at least every 28 days. Vehicle unit data at least every 90 days.', 'The card''s period is shorter than the vehicle unit''s.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'et', 'Kui tihti tuleb juhikaardi andmed alla laadida?', '["Iga 7 päeva järel","Iga 28 päeva järel","Iga 90 päeva järel","Kord aastas"]'::jsonb, 1, 'Juhikaardi andmed laaditakse alla vähemalt iga 28 päeva järel. Sõidukiüksuse andmed vähemalt iga 90 päeva järel.', 'Kaardi tähtaeg on lühem kui sõidukiüksusel.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'ru', 'Как часто нужно скачивать данные с карты водителя?', '["Раз в 7 дней","Раз в 28 дней","Раз в 90 дней","Раз в год"]'::jsonb, 1, 'Данные карты водителя скачиваются не реже чем раз в 28 дней. Данные бортового блока — не реже раза в 90 дней.', 'Для карты срок короче, чем для блока.', 'Регламент (ЕС) 581/2010'),
  ('tacho', 'tacho.c2', 'sv', 'Hur ofta ska förarkortets data laddas ner?', '["Var 7:e dag","Var 28:e dag","Var 90:e dag","En gång om året"]'::jsonb, 1, 'Förarkortets data laddas ner minst var 28:e dag. Fordonsenhetens data minst var 90:e dag.', 'Kortets period är kortare än fordonsenhetens.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'lv', 'Cik bieži jālejupielādē vadītāja kartes dati?', '["Reizi 7 dienās","Reizi 28 dienās","Reizi 90 dienās","Reizi gadā"]'::jsonb, 1, 'Vadītāja kartes datus lejupielādē ne retāk kā reizi 28 dienās. Transportlīdzekļa bloka datus — ne retāk kā reizi 90 dienās.', 'Kartei termiņš ir īsāks nekā blokam.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'lt', 'Kaip dažnai reikia atsisiųsti vairuotojo kortelės duomenis?', '["Kas 7 dienas","Kas 28 dienas","Kas 90 dienų","Kartą per metus"]'::jsonb, 1, 'Vairuotojo kortelės duomenys atsisiunčiami ne rečiau kaip kas 28 dienas. Transporto priemonės bloko duomenys – ne rečiau kaip kas 90 dienų.', 'Kortelės terminas trumpesnis nei bloko.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'pl', 'Jak często trzeba pobierać dane z karty kierowcy?', '["Co 7 dni","Co 28 dni","Co 90 dni","Raz w roku"]'::jsonb, 1, 'Dane z karty kierowcy pobiera się nie rzadziej niż co 28 dni. Dane z jednostki pojazdowej – nie rzadziej niż co 90 dni.', 'Dla karty termin jest krótszy niż dla jednostki.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'nb', 'Hvor ofte må data fra sjåførkortet lastes ned?', '["Hver 7. dag","Hver 28. dag","Hver 90. dag","Én gang i året"]'::jsonb, 1, 'Data fra sjåførkortet lastes ned minst hver 28. dag. Data fra kjøretøyenheten minst hver 90. dag.', 'Kortets frist er kortere enn kjøretøyenhetens.', '(EU) 581/2010'),
  ('tacho', 'tacho.c2', 'da', 'Hvor ofte skal data fra førerkortet downloades?', '["Hver 7. dag","Hver 28. dag","Hver 90. dag","Én gang om året"]'::jsonb, 1, 'Data fra førerkortet downloades mindst hver 28. dag. Data fra køretøjsenheden mindst hver 90. dag.', 'Kortets frist er kortere end køretøjsenhedens.', '(EU) 581/2010'),
  ('tacho', 'tacho.c3', 'fi', 'Kuljettajakortti hajosi keikalla. Mikä pitää paikkansa?', '["Lopetan työt heti","Ajan ilman merkintöjä ja kirjaan myöhemmin","Ilmoitan ja haen uutta 7 päivän kuluessa; enintään 15 päivää ajan tulosteiden kanssa vuoron alussa ja lopussa","Otan työkaverin kortin"]'::jsonb, 2, 'Kortin viasta tai katoamisesta ilmoitetaan viranomaisille ja uutta haetaan 7 kalenteripäivän kuluessa. Ilman korttia saa ajaa enintään 15 päivää, kun tulostaa ja allekirjoittaa tulosteet vuoron alussa ja lopussa.', 'Toisen kuljettajan korttia ei saa käyttää koskaan.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'en', 'Your driver card broke during a trip. What is correct?', '["I stop work immediately","I drive without records and write them down later","I report it and apply for a replacement within 7 days; for up to 15 days I drive with printouts at the start and end of the shift","I use a colleague''s card"]'::jsonb, 2, 'A faulty or lost card is reported to the authorities and a replacement applied for within 7 calendar days. You may drive without the card for up to 15 days, making and signing printouts at the start and end of each shift.', 'Never use someone else''s card.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'et', 'Juhikaart läks reisil katki. Mis on õige?', '["Lõpetan kohe töö","Sõidan ilma salvestuseta, kirjutan hiljem","Teatan ja taotlen asenduskaardi 7 päeva jooksul; kuni 15 päeva sõidan väljatrükkidega vahetuse alguses ja lõpus","Võtan kolleegi kaardi"]'::jsonb, 2, 'Kaardi rikkest või kaotusest teatatakse ametiasutustele ja asenduskaarti taotletakse 7 kalendripäeva jooksul. Ilma kaardita võib sõita kuni 15 päeva, tehes vahetuse alguses ja lõpus väljatrükid ja allkirjastades need.', 'Teise inimese kaarti ei tohi kunagi kasutada.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'ru', 'Карта водителя сломалась в рейсе. Что верно?', '["Сразу прекращаю работу","Езжу без записи, запишу потом","Заявляю, прошу замену в течение 7 дней; до 15 дней езжу с распечатками в начале и конце смены","Беру карту коллеги"]'::jsonb, 2, 'О неисправности или утере карты сообщают властям и подают на замену в течение 7 календарных дней. Ездить без карты можно до 15 дней, делая распечатки в начале и в конце смены и подписывая их.', 'Чужую карту использовать нельзя никогда.', '165/2014, ст. 29, 35'),
  ('tacho', 'tacho.c3', 'sv', 'Förarkortet gick sönder under en körning. Vad stämmer?', '["Jag slutar jobba direkt","Jag kör utan registrering och skriver upp det senare","Jag anmäler och ansöker om nytt inom 7 dagar; i upp till 15 dagar kör jag med utskrifter i början och slutet av skiftet","Jag tar en kollegas kort"]'::jsonb, 2, 'Ett trasigt eller förlorat kort anmäls till myndigheterna och nytt kort söks inom 7 kalenderdagar. Utan kort får du köra i upp till 15 dagar om du gör och skriver under utskrifter i början och slutet av varje skift.', 'Någon annans kort får aldrig användas.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'lv', 'Vadītāja karte reisā sabojājās. Kas ir pareizi?', '["Uzreiz pārtraucu darbu","Braucu bez ieraksta, pierakstīšu vēlāk","Ziņoju un pieprasu nomaiņu 7 dienu laikā; līdz 15 dienām braucu ar izdrukām maiņas sākumā un beigās","Ņemu kolēģa karti"]'::jsonb, 2, 'Par kartes bojājumu vai nozaudēšanu ziņo iestādēm un nomaiņu pieprasa 7 kalendāro dienu laikā. Bez kartes drīkst braukt līdz 15 dienām, maiņas sākumā un beigās taisot izdrukas un tās parakstot.', 'Svešu karti izmantot nedrīkst nekad.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'lt', 'Vairuotojo kortelė sugedo reiso metu. Kas teisinga?', '["Iš karto nutraukiu darbą","Važiuoju be įrašo, užrašysiu vėliau","Pranešu ir per 7 dienas prašau pakeitimo; iki 15 dienų važiuoju su spaudiniais pamainos pradžioje ir pabaigoje","Imu kolegos kortelę"]'::jsonb, 2, 'Apie kortelės gedimą ar praradimą pranešama institucijoms ir per 7 kalendorines dienas prašoma pakeitimo. Be kortelės galima važiuoti iki 15 dienų, pamainos pradžioje ir pabaigoje darant spaudinius ir juos pasirašant.', 'Svetimos kortelės naudoti negalima niekada.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'pl', 'Karta kierowcy zepsuła się w trasie. Co jest prawdą?', '["Od razu przerywam pracę","Jeżdżę bez zapisu, zapiszę później","Zgłaszam i wnioskuję o wymianę w ciągu 7 dni; do 15 dni jeżdżę z wydrukami na początku i końcu zmiany","Biorę kartę kolegi"]'::jsonb, 2, 'Usterkę lub utratę karty zgłasza się władzom i składa wniosek o wymianę w ciągu 7 dni kalendarzowych. Bez karty można jeździć do 15 dni, robiąc wydruki na początku i końcu zmiany i podpisując je.', 'Cudzej karty nie wolno używać nigdy.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'nb', 'Sjåførkortet ble ødelagt underveis. Hva er riktig?', '["Jeg slutter å jobbe med en gang","Jeg kjører uten registrering og skriver det ned senere","Jeg melder fra og søker om nytt innen 7 dager; i opptil 15 dager kjører jeg med utskrifter ved start og slutt av skiftet","Jeg tar en kollegas kort"]'::jsonb, 2, 'Et defekt eller tapt kort meldes til myndighetene, og nytt kort søkes innen 7 kalenderdager. Uten kort kan du kjøre i opptil 15 dager hvis du tar og signerer utskrifter ved start og slutt av hvert skift.', 'Andres kort skal aldri brukes.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c3', 'da', 'Førerkortet gik i stykker under en tur. Hvad er rigtigt?', '["Jeg stopper arbejdet med det samme","Jeg kører uden registrering og skriver det op senere","Jeg anmelder det og søger om nyt inden 7 dage; i op til 15 dage kører jeg med udskrifter ved start og slut på vagten","Jeg bruger en kollegas kort"]'::jsonb, 2, 'Et defekt eller mistet kort anmeldes til myndighederne, og der søges om nyt inden 7 kalenderdage. Uden kort må du køre i op til 15 dage, hvis du laver og underskriver udskrifter ved start og slut på hver vagt.', 'En andens kort må aldrig bruges.', '165/2014, art. 29, 35'),
  ('tacho', 'tacho.c4', 'fi', 'Ylitit rajan. Mitä teet piirturille (jos se ei tallenna sitä itse)?', '["En mitään","Syötän maatunnuksen ensimmäisellä mahdollisella pysähdyspaikalla rajan jälkeen","Syötän maan vasta vuoron lopussa","Otan tulosteen"]'::jsonb, 1, 'Maatunnus syötetään ensimmäisellä mahdollisella pysähdyspaikalla rajan ylittämisen jälkeen. Toisen sukupolven älypiirturit tekevät sen automaattisesti.', 'Ei ajon aikana — ensimmäisellä pysähdyksellä.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'en', 'You crossed a border. What do you do with the tachograph (if it doesn''t record it itself)?', '["Nothing","Enter the country symbol at the first possible stop after the border","Enter the country only at the end of the shift","Make a printout"]'::jsonb, 1, 'The country symbol is entered at the first possible stopping place after crossing the border. Second-generation smart tachographs do this automatically.', 'Not while driving — at the first stop.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'et', 'Ületasid piiri. Mida teed sõidumeerikuga (kui see ise ei salvesta)?', '["Mitte midagi","Sisestan riigi sümboli esimeses võimalikus peatuskohas pärast piiri","Sisestan riigi alles vahetuse lõpus","Teen väljatrüki"]'::jsonb, 1, 'Riigi sümbol sisestatakse esimeses võimalikus peatuskohas pärast piiri ületamist. Teise põlvkonna nutikad sõidumeerikud teevad seda automaatselt.', 'Mitte sõidu ajal — esimeses peatuses.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'ru', 'Пересёк границу. Что делаешь с тахографом (если он не записывает это сам)?', '["Ничего","Ввожу символ страны на первой возможной остановке после границы","Ввожу страну только в конце смены","Делаю распечатку"]'::jsonb, 1, 'Символ страны вводится на первом возможном месте остановки после пересечения границы. Смарт-тахографы второго поколения делают это автоматически.', 'Не на ходу — на первой остановке.', '165/2014, ст. 34(7)'),
  ('tacho', 'tacho.c4', 'sv', 'Du har passerat en gräns. Vad gör du med färdskrivaren (om den inte registrerar det själv)?', '["Ingenting","Anger landssymbolen på första möjliga stopp efter gränsen","Anger landet först i slutet av skiftet","Tar en utskrift"]'::jsonb, 1, 'Landssymbolen anges på första möjliga stoppställe efter gränspassagen. Smarta färdskrivare av andra generationen gör det automatiskt.', 'Inte under körning — vid första stoppet.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'lv', 'Šķērsoji robežu. Ko dari ar tahogrāfu (ja tas pats to nereģistrē)?', '["Neko","Ievadu valsts simbolu pirmajā iespējamajā apstāšanās vietā pēc robežas","Ievadu valsti tikai maiņas beigās","Taisu izdruku"]'::jsonb, 1, 'Valsts simbolu ievada pirmajā iespējamajā apstāšanās vietā pēc robežas šķērsošanas. Otrās paaudzes viedie tahogrāfi to dara automātiski.', 'Ne braucot — pirmajā pieturā.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'lt', 'Kirtai sieną. Ką darai su tachografu (jei jis pats to neįrašo)?', '["Nieko","Įvedu šalies simbolį pirmoje įmanomoje sustojimo vietoje po sienos","Šalį įvedu tik pamainos pabaigoje","Darau spaudinį"]'::jsonb, 1, 'Šalies simbolis įvedamas pirmoje įmanomoje sustojimo vietoje kirtus sieną. Antrosios kartos išmanieji tachografai tai daro automatiškai.', 'Ne važiuojant – pirmame sustojime.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'pl', 'Przekroczyłeś granicę. Co robisz z tachografem (jeśli sam tego nie zapisuje)?', '["Nic","Wprowadzam symbol kraju na pierwszym możliwym postoju po granicy","Wprowadzam kraj dopiero na koniec zmiany","Robię wydruk"]'::jsonb, 1, 'Symbol kraju wprowadza się na pierwszym możliwym miejscu postoju po przekroczeniu granicy. Inteligentne tachografy drugiej generacji robią to automatycznie.', 'Nie w trakcie jazdy – na pierwszym postoju.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'nb', 'Du har krysset en grense. Hva gjør du med fartsskriveren (hvis den ikke registrerer det selv)?', '["Ingenting","Legger inn landssymbolet på første mulige stopp etter grensen","Legger inn landet først ved slutten av skiftet","Tar en utskrift"]'::jsonb, 1, 'Landssymbolet legges inn på første mulige stoppested etter grensepasseringen. Smarte fartsskrivere av andre generasjon gjør det automatisk.', 'Ikke under kjøring — ved første stopp.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c4', 'da', 'Du har krydset en grænse. Hvad gør du med fartskriveren (hvis den ikke registrerer det selv)?', '["Ingenting","Indtaster landesymbolet ved første mulige stop efter grænsen","Indtaster landet først ved vagtens slutning","Tager en udskrift"]'::jsonb, 1, 'Landesymbolet indtastes ved første mulige standsningssted efter grænsepassagen. Intelligente fartskrivere af anden generation gør det automatisk.', 'Ikke under kørsel — ved første stop.', '165/2014, art. 34(7)'),
  ('tacho', 'tacho.c5', 'fi', 'Mitä ristikkäiset vasarat tarkoittavat?', '["Ajo","Muu työ","Valmiusaika","Lepo"]'::jsonb, 1, 'Vasarat — muu työ. Ratti — ajo. Neliö, jossa vinoviiva — valmiusaika. Sänky — lepo ja tauko.', 'Vasara on työkalu.', '165/2014, liite IC'),
  ('tacho', 'tacho.c5', 'en', 'What does the crossed hammers symbol mean?', '["Driving","Other work","Availability","Rest"]'::jsonb, 1, 'Hammers — other work. Steering wheel — driving. Square with a diagonal — availability. Bed — rest and break.', 'A hammer is a work tool.', '165/2014, Annex IC'),
  ('tacho', 'tacho.c5', 'et', 'Mida tähendab ristatud haamrite sümbol?', '["Sõit","Muu töö","Valmisolek","Puhkus"]'::jsonb, 1, 'Haamrid — muu töö. Rool — sõit. Diagonaaliga ruut — valmisolek. Voodi — puhkus ja paus.', 'Haamer on töövahend.', '165/2014, lisa IC'),
  ('tacho', 'tacho.c5', 'ru', 'Что означает символ скрещённых молотков?', '["Вождение","Другая работа","Готовность","Отдых"]'::jsonb, 1, 'Молотки — другая работа. Руль — вождение. Квадрат с диагональю — готовность. Кровать — отдых и перерыв.', 'Молоток — инструмент работы.', '165/2014, Приложение IC'),
  ('tacho', 'tacho.c5', 'sv', 'Vad betyder symbolen med korsade hammare?', '["Körning","Annat arbete","Tillgänglighet","Vila"]'::jsonb, 1, 'Hammare — annat arbete. Ratt — körning. Fyrkant med diagonal — tillgänglighet. Säng — vila och rast.', 'En hammare är ett arbetsverktyg.', '165/2014, bilaga IC'),
  ('tacho', 'tacho.c5', 'lv', 'Ko nozīmē sakrustotu āmuru simbols?', '["Braukšana","Cits darbs","Gatavība","Atpūta"]'::jsonb, 1, 'Āmuri — cits darbs. Stūre — braukšana. Kvadrāts ar diagonāli — gatavība. Gulta — atpūta un pārtraukums.', 'Āmurs ir darba rīks.', '165/2014, pielikums IC'),
  ('tacho', 'tacho.c5', 'lt', 'Ką reiškia sukryžiuotų plaktukų simbolis?', '["Vairavimas","Kitas darbas","Budėjimas","Poilsis"]'::jsonb, 1, 'Plaktukai – kitas darbas. Vairas – vairavimas. Kvadratas su įstrižaine – budėjimas. Lova – poilsis ir pertrauka.', 'Plaktukas – darbo įrankis.', '165/2014, priedas IC'),
  ('tacho', 'tacho.c5', 'pl', 'Co oznacza symbol skrzyżowanych młotków?', '["Jazda","Inna praca","Dyspozycyjność","Odpoczynek"]'::jsonb, 1, 'Młotki – inna praca. Kierownica – jazda. Kwadrat z przekątną – dyspozycyjność. Łóżko – odpoczynek i przerwa.', 'Młotek to narzędzie pracy.', '165/2014, załącznik IC'),
  ('tacho', 'tacho.c5', 'nb', 'Hva betyr symbolet med kryssede hammere?', '["Kjøring","Annet arbeid","Tilgjengelighet","Hvil"]'::jsonb, 1, 'Hammere — annet arbeid. Ratt — kjøring. Firkant med diagonal — tilgjengelighet. Seng — hvil og pause.', 'En hammer er et arbeidsverktøy.', '165/2014, vedlegg IC'),
  ('tacho', 'tacho.c5', 'da', 'Hvad betyder symbolet med krydsede hamre?', '["Kørsel","Andet arbejde","Rådighed","Hvil"]'::jsonb, 1, 'Hamre — andet arbejde. Rat — kørsel. Firkant med diagonal — rådighed. Seng — hvil og pause.', 'En hammer er et arbejdsredskab.', '165/2014, bilag IC'),
  ('tacho', 'tacho.x1', 'fi', 'Kotiin viikkolevolle on 1,5 h matkaa, mutta ajoaika on täynnä. Mikä on sallittua?', '["Ei mitään, on pysähdyttävä","Ajaa perille, jos juuri ennen on pidetty 30 min tauko, ja kirjata syy käsin","Ajaa perille ilman ehtoja","Soittaa ajojärjestelijälle, joka antaa luvan"]'::jsonb, 1, 'Poikkeustilanteessa rajan saa ylittää enintään 1 h, ja enintään 2 h, jos juuri ennen on pidetty yhtäjaksoinen 30 min tauko, jotta pääsee kotiin tai toimipaikalle säännölliselle viikkolevolle. Syy kirjataan käsin, ja ylitys korvataan.', 'Poikkeus on olemassa, mutta ehdoin ja kirjauksin.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'en', 'You are 1.5 h from home for your weekly rest, but your driving time is used up. What is allowed?', '["Nothing, you must stop","Drive on if you took a 30 min break just before, and record the reason manually","Drive on without conditions","Call the dispatcher, who will allow it"]'::jsonb, 1, 'In exceptional cases you may exceed the limit by up to 1 h, or up to 2 h if you took an uninterrupted 30 min break immediately before, to reach home or base for a regular weekly rest. The reason must be recorded manually and the excess compensated.', 'There is an exception, but with conditions and documentation.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'et', 'Koju iganädalasele puhkusele on jäänud 1,5 h, aga sõiduaeg on täis. Mis on lubatud?', '["Mitte midagi, tuleb peatuda","Sõita kohale, kui vahetult enne oli 30 min paus, ja märkida põhjus käsitsi","Sõita kohale tingimusteta","Helistada dispetšerile, kes lubab"]'::jsonb, 1, 'Erandjuhul võib piirangut ületada kuni 1 h ja kuni 2 h, kui vahetult enne tehti katkematu 30 min paus, et jõuda koju või baasi regulaarsele iganädalasele puhkeajale. Põhjus tuleb märkida käsitsi ja ületamine hüvitada.', 'Erand on olemas, aga tingimuste ja dokumenteerimisega.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'ru', 'До места еженедельного отдыха дома осталось 1,5 ч, а лимит вождения исчерпан. Что разрешено?', '["Ничего, нужно встать","Доехать, если перед этим был перерыв 30 мин, и записать причину вручную","Доехать без условий","Позвонить диспетчеру — он разрешит"]'::jsonb, 1, 'В исключительных случаях можно превысить лимит до 1 ч, а до 2 ч — если сразу перед этим сделан непрерывный перерыв 30 мин, чтобы добраться домой или на базу на регулярный еженедельный отдых. Причину нужно записать вручную, а превышение компенсировать.', 'Исключение есть, но с условиями и документированием.', '561/2006, ст. 12'),
  ('tacho', 'tacho.x1', 'sv', 'Det är 1,5 h kvar hem till veckovilan, men körtiden är slut. Vad är tillåtet?', '["Ingenting, du måste stanna","Köra hem om du tog 30 min rast precis innan, och ange orsaken manuellt","Köra hem utan villkor","Ringa trafikledaren och få lov"]'::jsonb, 1, 'I undantagsfall får gränsen överskridas med upp till 1 h, och upp till 2 h om du tog en oavbruten rast på 30 min direkt innan, för att nå hemmet eller basen för normal veckovila. Orsaken ska anges manuellt och överskridandet kompenseras.', 'Undantaget finns, men med villkor och dokumentation.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'lv', 'Līdz iknedēļas atpūtai mājās atlikušas 1,5 h, bet braukšanas limits izsmelts. Kas atļauts?', '["Nekas, jāapstājas","Aizbraukt, ja tieši pirms tam bija 30 min pārtraukums, un pierakstīt iemeslu manuāli","Aizbraukt bez nosacījumiem","Piezvanīt dispečeram, kurš atļaus"]'::jsonb, 1, 'Izņēmuma gadījumos limitu drīkst pārsniegt līdz 1 h, bet līdz 2 h — ja tieši pirms tam ieturēts nepārtraukts 30 min pārtraukums, lai nokļūtu mājās vai bāzē uz regulāro iknedēļas atpūtu. Iemesls jāpieraksta manuāli, bet pārsniegums jākompensē.', 'Izņēmums ir, bet ar nosacījumiem un dokumentēšanu.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'lt', 'Iki savaitinio poilsio namuose liko 1,5 val., o vairavimo limitas išnaudotas. Kas leidžiama?', '["Nieko, reikia sustoti","Nuvažiuoti, jei prieš tai buvo 30 min. pertrauka, ir priežastį įrašyti ranka","Nuvažiuoti be sąlygų","Paskambinti dispečeriui, kuris leis"]'::jsonb, 1, 'Išimtiniais atvejais limitą galima viršyti iki 1 val., o iki 2 val. – jei prieš pat tai padaryta nepertraukiama 30 min. pertrauka, kad pasiektum namus ar bazę reguliariajam savaitiniam poilsiui. Priežastį reikia įrašyti ranka, o viršijimą kompensuoti.', 'Išimtis yra, bet su sąlygomis ir dokumentavimu.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'pl', 'Do domu na tygodniowy odpoczynek zostało 1,5 godz., a limit jazdy jest wyczerpany. Co wolno?', '["Nic, trzeba stanąć","Dojechać, jeśli tuż przedtem była przerwa 30 min, i ręcznie zapisać powód","Dojechać bez warunków","Zadzwonić do dyspozytora, który pozwoli"]'::jsonb, 1, 'W wyjątkowych przypadkach można przekroczyć limit do 1 godz., a do 2 godz. – jeśli tuż przedtem była nieprzerwana przerwa 30 min, aby dotrzeć do domu lub bazy na regularny tygodniowy odpoczynek. Powód trzeba zapisać ręcznie, a przekroczenie zrekompensować.', 'Wyjątek istnieje, ale z warunkami i dokumentacją.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'nb', 'Det er 1,5 t igjen hjem til ukehvilen, men kjøretiden er brukt opp. Hva er tillatt?', '["Ingenting, du må stoppe","Kjøre hjem hvis du tok 30 min pause rett før, og føre opp årsaken manuelt","Kjøre hjem uten vilkår","Ringe disponenten og få lov"]'::jsonb, 1, 'I unntakstilfeller kan grensen overskrides med opptil 1 t, og opptil 2 t hvis du tok en sammenhengende pause på 30 min rett før, for å nå hjemmet eller basen for vanlig ukehvil. Årsaken må føres opp manuelt og overskridelsen kompenseres.', 'Unntaket finnes, men med vilkår og dokumentasjon.', '561/2006, art. 12'),
  ('tacho', 'tacho.x1', 'da', 'Der er 1,5 t hjem til det ugentlige hvil, men køretiden er brugt op. Hvad er tilladt?', '["Ingenting, du skal holde stille","Køre hjem, hvis du holdt 30 min pause lige før, og notere årsagen manuelt","Køre hjem uden betingelser","Ringe til disponenten og få lov"]'::jsonb, 1, 'I ekstraordinære tilfælde må grænsen overskrides med op til 1 t, og op til 2 t hvis du holdt en uafbrudt pause på 30 min lige før, for at nå hjem eller til basen til regelmæssigt ugentligt hvil. Årsagen skal noteres manuelt og overskridelsen kompenseres.', 'Undtagelsen findes, men med betingelser og dokumentation.', '561/2006, art. 12'),
  ('tacho', 'tacho.x2', 'fi', 'Vuorokausilepo lautalla: kuinka monta kertaa sen saa keskeyttää?', '["Ei saa keskeyttää","Enintään 2 kertaa, yhteensä enintään 1 h, jos käytössä on makuupaikka","Niin monta kertaa kuin haluaa","Kerran enintään 2 h"]'::jsonb, 1, 'Lepoa lautalla tai junassa saa keskeyttää enintään kaksi kertaa, yhteensä enintään tunnin. Kuljettajalla on oltava käytössään makuupaikka.', 'Kaksi kertaa, yksi tunti.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'en', 'Daily rest on a ferry: how many times may it be interrupted?', '["It may not be interrupted","No more than twice, no more than 1 h in total, with access to a sleeping berth","As many times as you like","Once for up to 2 h"]'::jsonb, 1, 'A rest on a ferry or train may be interrupted no more than twice, for no more than an hour in total. The driver must have access to a sleeping berth.', 'Twice, one hour.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'et', 'Igapäevane puhkeaeg praamil: mitu korda tohib seda katkestada?', '["Katkestada ei tohi","Mitte rohkem kui 2 korda, kokku mitte üle 1 h, kui on magamiskoht","Nii mitu korda kui vaja","Üks kord kuni 2 h"]'::jsonb, 1, 'Puhkeaega praamil või rongis võib katkestada kõige rohkem kaks korda, kokku mitte üle tunni. Juhil peab olema juurdepääs magamiskohale.', 'Kaks korda, üks tund.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'ru', 'Ежедневный отдых на пароме: сколько раз можно его прервать?', '["Нельзя прерывать","Не более 2 раз, в сумме не более 1 ч, при наличии спального места","Сколько угодно","Один раз до 2 ч"]'::jsonb, 1, 'Отдых на пароме или поезде можно прервать не более двух раз, в сумме не более часа. Водитель должен иметь доступ к спальному месту.', 'Два раза, один час.', '561/2006, ст. 9'),
  ('tacho', 'tacho.x2', 'sv', 'Dygnsvila på färja: hur många gånger får den avbrytas?', '["Den får inte avbrytas","Högst 2 gånger, sammanlagt högst 1 h, med tillgång till sovplats","Hur många gånger som helst","En gång i upp till 2 h"]'::jsonb, 1, 'Vila på färja eller tåg får avbrytas högst två gånger, sammanlagt högst en timme. Föraren ska ha tillgång till sovplats.', 'Två gånger, en timme.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'lv', 'Ikdienas atpūta uz prāmja: cik reizes to drīkst pārtraukt?', '["Pārtraukt nedrīkst","Ne vairāk kā 2 reizes, kopā ne vairāk kā 1 h, ja ir guļvieta","Cik reizes vien vajag","Vienreiz līdz 2 h"]'::jsonb, 1, 'Atpūtu uz prāmja vai vilciena drīkst pārtraukt ne vairāk kā divas reizes, kopā ne ilgāk par stundu. Vadītājam jābūt pieejamai guļvietai.', 'Divas reizes, viena stunda.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'lt', 'Kasdienis poilsis kelte: kiek kartų jį galima nutraukti?', '["Nutraukti negalima","Ne daugiau kaip 2 kartus, iš viso ne daugiau kaip 1 val., jei yra miegamoji vieta","Kiek nori","Vieną kartą iki 2 val."]'::jsonb, 1, 'Poilsį kelte ar traukinyje galima nutraukti ne daugiau kaip du kartus, iš viso ne ilgiau kaip valandą. Vairuotojas turi turėti galimybę naudotis miegamąja vieta.', 'Du kartai, viena valanda.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'pl', 'Dzienny odpoczynek na promie: ile razy można go przerwać?', '["Nie można przerywać","Nie więcej niż 2 razy, łącznie nie dłużej niż 1 godz., przy dostępie do miejsca do spania","Ile razy się chce","Raz do 2 godz."]'::jsonb, 1, 'Odpoczynek na promie lub w pociągu można przerwać nie więcej niż dwa razy, łącznie nie dłużej niż godzinę. Kierowca musi mieć dostęp do miejsca do spania.', 'Dwa razy, jedna godzina.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'nb', 'Døgnhvil på ferje: hvor mange ganger kan den avbrytes?', '["Den kan ikke avbrytes","Høyst 2 ganger, til sammen høyst 1 t, med tilgang til soveplass","Så mange ganger du vil","Én gang i opptil 2 t"]'::jsonb, 1, 'Hvil på ferje eller tog kan avbrytes høyst to ganger, til sammen høyst én time. Sjåføren må ha tilgang til soveplass.', 'To ganger, én time.', '561/2006, art. 9'),
  ('tacho', 'tacho.x2', 'da', 'Dagligt hvil på færge: hvor mange gange må det afbrydes?', '["Det må ikke afbrydes","Højst 2 gange, i alt højst 1 t, med adgang til sovekøje","Så mange gange du vil","Én gang i op til 2 t"]'::jsonb, 1, 'Hvil på færge eller tog må afbrydes højst to gange, i alt højst én time. Chaufføren skal have adgang til en sovekøje.', 'To gange, én time.', '561/2006, art. 9'),
  ('cargo', 'cargo.g1', 'fi', 'Mille voimalle kuorman sidonta eteenpäin (jarrutuksessa) mitoitetaan?', '["0,3 × kuorman paino","0,5 × kuorman paino","0,8 × kuorman paino","1,0 × kuorman paino"]'::jsonb, 2, 'Maantiekuljetuksissa sidonta eteenpäin mitoitetaan 0,8 g:lle eli 80 %:lle kuorman painosta.', 'Eteenpäin suuntautuva voima on suurin kaikista suunnista.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'en', 'What inertial force is forward cargo securing (braking) designed for?', '["0.3 of the cargo weight","0.5 of the cargo weight","0.8 of the cargo weight","1.0 of the cargo weight"]'::jsonb, 2, 'For road transport, forward securing is designed for 0.8 g — that is 80% of the cargo weight.', 'Forward is the largest force of all directions.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'et', 'Millisele inertsjõule arvutatakse koorma kinnitus ettesuunas (pidurdamisel)?', '["0,3 koorma kaalust","0,5 koorma kaalust","0,8 koorma kaalust","1,0 koorma kaalust"]'::jsonb, 2, 'Maanteeveol arvutatakse kinnitus ettesuunas 0,8 g-le — see on 80% koorma kaalust.', 'Ettesuunas on jõud kõigist suundadest suurim.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'ru', 'На какую силу инерции рассчитывают крепление груза вперёд (при торможении)?', '["0,3 от веса груза","0,5 от веса груза","0,8 от веса груза","1,0 от веса груза"]'::jsonb, 2, 'Для дорожных перевозок крепление вперёд рассчитывают на 0,8 g — это 80% веса груза.', 'Вперёд — самая большая сила из всех направлений.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'sv', 'Vilken tröghetskraft dimensioneras lastsäkringen framåt (vid inbromsning) för?', '["0,3 av lastens vikt","0,5 av lastens vikt","0,8 av lastens vikt","1,0 av lastens vikt"]'::jsonb, 2, 'Vid vägtransport dimensioneras säkringen framåt för 0,8 g — det är 80 % av lastens vikt.', 'Framåt är den största kraften av alla riktningar.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'lv', 'Kādam inerces spēkam aprēķina kravas nostiprināšanu uz priekšu (bremzējot)?', '["0,3 no kravas svara","0,5 no kravas svara","0,8 no kravas svara","1,0 no kravas svara"]'::jsonb, 2, 'Autopārvadājumos nostiprinājumu uz priekšu aprēķina 0,8 g — tas ir 80% no kravas svara.', 'Uz priekšu ir lielākais spēks no visiem virzieniem.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'lt', 'Kokiai inercijos jėgai skaičiuojamas krovinio tvirtinimas į priekį (stabdant)?', '["0,3 krovinio svorio","0,5 krovinio svorio","0,8 krovinio svorio","1,0 krovinio svorio"]'::jsonb, 2, 'Kelių transportui tvirtinimas į priekį skaičiuojamas 0,8 g – tai 80 % krovinio svorio.', 'Į priekį – didžiausia jėga iš visų krypčių.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'pl', 'Na jaką siłę bezwładności oblicza się mocowanie ładunku do przodu (przy hamowaniu)?', '["0,3 ciężaru ładunku","0,5 ciężaru ładunku","0,8 ciężaru ładunku","1,0 ciężaru ładunku"]'::jsonb, 2, 'W transporcie drogowym mocowanie do przodu oblicza się na 0,8 g – to 80% ciężaru ładunku.', 'Do przodu działa największa siła ze wszystkich kierunków.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'nb', 'Hvilken treghetskraft dimensjoneres lastsikring forover (ved bremsing) for?', '["0,3 av lastens vekt","0,5 av lastens vekt","0,8 av lastens vekt","1,0 av lastens vekt"]'::jsonb, 2, 'Ved veitransport dimensjoneres sikring forover for 0,8 g — det er 80 % av lastens vekt.', 'Forover er den største kraften av alle retninger.', 'EN 12195-1'),
  ('cargo', 'cargo.g1', 'da', 'Hvilken inertikraft dimensioneres lastsikring fremad (ved opbremsning) til?', '["0,3 af lastens vægt","0,5 af lastens vægt","0,8 af lastens vægt","1,0 af lastens vægt"]'::jsonb, 2, 'Ved vejtransport dimensioneres sikring fremad til 0,8 g — det er 80 % af lastens vægt.', 'Fremad er den største kraft af alle retninger.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'fi', 'Entä mille voimalle sidonta sivuille ja taaksepäin mitoitetaan?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Sivuille ja taaksepäin 0,5 g eli puolet kuorman painosta.', 'Puolet.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'en', 'And what force is securing sideways and backwards designed for?', '["0.5 g","0.8 g","0.2 g","1.0 g"]'::jsonb, 0, 'Sideways and backwards — 0.5 g, i.e. half the cargo weight.', 'Half.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'et', 'Aga millisele jõule arvutatakse kinnitus külgedele ja tahapoole?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Külgedele ja tahapoole — 0,5 g ehk pool koorma kaalust.', 'Pool.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'ru', 'А на какую силу рассчитывают крепление вбок и назад?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Вбок и назад — 0,5 g, то есть половина веса груза.', 'Половина.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'sv', 'Och vilken kraft dimensioneras säkringen i sidled och bakåt för?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'I sidled och bakåt — 0,5 g, alltså halva lastens vikt.', 'Hälften.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'lv', 'Un kādam spēkam aprēķina nostiprinājumu uz sāniem un atpakaļ?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Uz sāniem un atpakaļ — 0,5 g, t. i., puse no kravas svara.', 'Puse.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'lt', 'O kokiai jėgai skaičiuojamas tvirtinimas į šonus ir atgal?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Į šonus ir atgal – 0,5 g, t. y. pusė krovinio svorio.', 'Pusė.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'pl', 'A na jaką siłę oblicza się mocowanie na boki i do tyłu?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Na boki i do tyłu – 0,5 g, czyli połowa ciężaru ładunku.', 'Połowa.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'nb', 'Og hvilken kraft dimensjoneres sikring sideveis og bakover for?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Sideveis og bakover — 0,5 g, altså halve lastens vekt.', 'Halvparten.', 'EN 12195-1'),
  ('cargo', 'cargo.g2', 'da', 'Og hvilken kraft dimensioneres sikring til siden og bagud til?', '["0,5 g","0,8 g","0,2 g","1,0 g"]'::jsonb, 0, 'Til siden og bagud — 0,5 g, altså halvdelen af lastens vægt.', 'Halvdelen.', 'EN 12195-1'),
  ('cargo', 'cargo.g3', 'fi', 'Mitä STF tarkoittaa sidontavyön etiketissä?', '["Suurin murtokuorma","Kiristysvoima, jonka räikkä antaa normaalilla käsivoimalla","Vyön pituus","Valmistusvuosi"]'::jsonb, 1, 'STF (Standard Tension Force) on räikän kiristysvoima daN:inä. Juuri se ratkaisee yliheittosidonnassa (vyö kuorman yli).', 'T-kirjain — tension, kiristys.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'en', 'What does STF on a lashing strap label mean?', '["Maximum breaking load","Tension force the ratchet gives with normal hand force","Strap length","Year of manufacture"]'::jsonb, 1, 'STF (Standard Tension Force) is the ratchet tension force in daN. It matters for top-over lashing (strap over the top of the cargo).', 'T stands for tension.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'et', 'Mida tähendab STF sidumisrihma sildil?', '["Maksimaalne purunemiskoormus","Pingutusjõud, mille põrkmehhanism annab tavalise käejõuga","Rihma pikkus","Valmistamisaasta"]'::jsonb, 1, 'STF (Standard Tension Force) on põrkmehhanismi pingutusjõud daN-des. Just see on oluline ülevalt üle kinnitamisel (rihm üle koorma).', 'T-täht — tension, pingutus.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'ru', 'Что означает STF на этикетке ремня?', '["Максимальная нагрузка на разрыв","Сила натяжения, которую даёт храповик при обычном усилии руки","Длина ремня","Год выпуска"]'::jsonb, 1, 'STF (Standard Tension Force) — сила натяжения храповиком в daN. Именно она важна при креплении прижимом (ремень через верх груза).', 'Буква T — tension, натяжение.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'sv', 'Vad betyder STF på spännbandets etikett?', '["Maximal brottlast","Spännkraften som spännaren ger med normal handkraft","Bandets längd","Tillverkningsår"]'::jsonb, 1, 'STF (Standard Tension Force) är spännarens spännkraft i daN. Den är avgörande vid överfallssurrning (band över lasten).', 'T står för tension, spänning.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'lv', 'Ko nozīmē STF uz stiprinājuma siksnas etiķetes?', '["Maksimālā pārrāvuma slodze","Nospriegojuma spēks, ko dod sprūdrats ar parastu rokas spēku","Siksnas garums","Izgatavošanas gads"]'::jsonb, 1, 'STF (Standard Tension Force) ir sprūdrata nospriegojuma spēks daN. Tieši tas ir svarīgs, piespiežot kravu (siksna pāri kravai).', 'Burts T — tension, nospriegojums.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'lt', 'Ką reiškia STF ant tvirtinimo diržo etiketės?', '["Didžiausia trūkimo apkrova","Įtempimo jėga, kurią terkšlė suteikia įprasta rankos jėga","Diržo ilgis","Pagaminimo metai"]'::jsonb, 1, 'STF (Standard Tension Force) – terkšlės įtempimo jėga daN. Būtent ji svarbi tvirtinant prispaudimu (diržas per krovinio viršų).', 'Raidė T – tension, įtempimas.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'pl', 'Co oznacza STF na etykiecie pasa?', '["Maksymalne obciążenie zrywające","Siła naciągu, jaką daje grzechotka przy normalnym nacisku ręki","Długość pasa","Rok produkcji"]'::jsonb, 1, 'STF (Standard Tension Force) to siła naciągu grzechotką w daN. To ona jest ważna przy mocowaniu dociskowym (pas przez górę ładunku).', 'Litera T – tension, naciąg.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'nb', 'Hva betyr STF på etiketten til en stroppe?', '["Maksimal bruddlast","Strammekraften skralla gir med vanlig håndkraft","Stroppens lengde","Produksjonsår"]'::jsonb, 1, 'STF (Standard Tension Force) er skrallens strammekraft i daN. Den er avgjørende ved overfallssurring (stroppe over lasten).', 'T står for tension, stramming.', 'EN 12195-2'),
  ('cargo', 'cargo.g3', 'da', 'Hvad betyder STF på en spændestrops etiket?', '["Maksimal brudlast","Spændekraften, som skralden giver med normal håndkraft","Stroppens længde","Produktionsår"]'::jsonb, 1, 'STF (Standard Tension Force) er skraldens spændekraft i daN. Den er afgørende ved overfaldssurring (strop over lasten).', 'T står for tension, stramning.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'fi', 'Mitä LC tarkoittaa sidontavyön etiketissä?', '["Vyön sallittu kuormitus suorassa sidonnassa","Räikän kiristysvoima","Kitkakerroin","Kuorman luokka"]'::jsonb, 0, 'LC (Lashing Capacity) on suurin voima, jonka vyö kestää suorassa sidonnassa (vyö kuormasta kiinnityspisteeseen).', 'Capacity — kapasiteetti, sallittu kuormitus.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'en', 'What does LC on a lashing strap label mean?', '["Permitted load on the strap in direct lashing","Ratchet tension force","Friction coefficient","Cargo class"]'::jsonb, 0, 'LC (Lashing Capacity) is the maximum force the strap can withstand in direct lashing (strap from the cargo to the lashing point).', 'Capacity — the permitted load.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'et', 'Mida tähendab LC sidumisrihma sildil?', '["Rihma lubatud koormus otsekinnitusel","Põrkmehhanismi pingutusjõud","Hõõrdetegur","Koorma klass"]'::jsonb, 0, 'LC (Lashing Capacity) on suurim jõud, mida rihm talub otsekinnitusel (rihm koormast kinnituspunktini).', 'Capacity — mahutavus, lubatud koormus.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'ru', 'Что означает LC на этикетке ремня?', '["Допустимая нагрузка на ремень при прямом креплении","Сила натяжения храповиком","Коэффициент трения","Класс груза"]'::jsonb, 0, 'LC (Lashing Capacity) — максимальная сила, которую ремень может выдержать при прямом креплении (ремень от груза к точке крепления).', 'Capacity — вместимость, допустимая нагрузка.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'sv', 'Vad betyder LC på spännbandets etikett?', '["Tillåten belastning på bandet vid direktsurrning","Spännarens spännkraft","Friktionstal","Lastklass"]'::jsonb, 0, 'LC (Lashing Capacity) är den största kraft bandet klarar vid direktsurrning (band från lasten till surrningspunkten).', 'Capacity — kapacitet, tillåten belastning.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'lv', 'Ko nozīmē LC uz stiprinājuma siksnas etiķetes?', '["Pieļaujamā slodze siksnai tiešā nostiprinājumā","Sprūdrata nospriegojuma spēks","Berzes koeficients","Kravas klase"]'::jsonb, 0, 'LC (Lashing Capacity) ir maksimālais spēks, ko siksna var izturēt tiešā nostiprinājumā (siksna no kravas līdz stiprinājuma punktam).', 'Capacity — ietilpība, pieļaujamā slodze.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'lt', 'Ką reiškia LC ant tvirtinimo diržo etiketės?', '["Leistina diržo apkrova tiesiogiai tvirtinant","Terkšlės įtempimo jėga","Trinties koeficientas","Krovinio klasė"]'::jsonb, 0, 'LC (Lashing Capacity) – didžiausia jėga, kurią diržas gali atlaikyti tiesiogiai tvirtinant (diržas nuo krovinio iki tvirtinimo taško).', 'Capacity – talpa, leistina apkrova.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'pl', 'Co oznacza LC na etykiecie pasa?', '["Dopuszczalne obciążenie pasa przy mocowaniu bezpośrednim","Siła naciągu grzechotką","Współczynnik tarcia","Klasa ładunku"]'::jsonb, 0, 'LC (Lashing Capacity) to maksymalna siła, jaką pas może wytrzymać przy mocowaniu bezpośrednim (pas od ładunku do punktu mocowania).', 'Capacity – pojemność, dopuszczalne obciążenie.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'nb', 'Hva betyr LC på etiketten til en stroppe?', '["Tillatt belastning på stroppen ved direkte surring","Skrallens strammekraft","Friksjonskoeffisient","Lastklasse"]'::jsonb, 0, 'LC (Lashing Capacity) er den største kraften stroppen tåler ved direkte surring (stroppe fra lasten til festepunktet).', 'Capacity — kapasitet, tillatt belastning.', 'EN 12195-2'),
  ('cargo', 'cargo.g4', 'da', 'Hvad betyder LC på en spændestrops etiket?', '["Tilladt belastning på stroppen ved direkte surring","Skraldens spændekraft","Friktionskoefficient","Lastklasse"]'::jsonb, 0, 'LC (Lashing Capacity) er den største kraft, stroppen kan klare ved direkte surring (strop fra lasten til surringspunktet).', 'Capacity — kapacitet, tilladt belastning.', 'EN 12195-2'),
  ('cargo', 'cargo.g5', 'fi', 'Kuorman yli kulkeva vyö on kiristetty 30° kulmaan lähes 90° sijaan. Mitä puristusvoimalle tapahtuu?', '["Se tuskin muuttuu","Se pienenee noin puoleen","Se kasvaa","Se pienenee 10 %"]'::jsonb, 1, 'Puristusvoima on verrannollinen kulman siniin: sin 90° = 1, sin 30° = 0,5. Loiva vyö puristaa puolet heikommin — vöitä tarvitaan kaksi kertaa enemmän.', 'Mitä jyrkempi vyö, sitä kovemmin se puristaa.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'en', 'A strap over the top of the cargo is tensioned at 30° instead of nearly 90°. What happens to the downward pressure?', '["It hardly changes","It drops by about half","It increases","It drops by 10%"]'::jsonb, 1, 'The pressure is proportional to the sine of the angle: sin 90° = 1, sin 30° = 0.5. A shallow strap presses half as hard — you need twice as many straps.', 'The steeper the strap, the harder it presses.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'et', 'Üle koorma rihm on pingutatud 30° nurga all peaaegu 90° asemel. Mis juhtub survejõuga?', '["Peaaegu ei muutu","Väheneb umbes poole võrra","Suureneb","Väheneb 10%"]'::jsonb, 1, 'Survejõud on võrdeline nurga siinusega: sin 90° = 1, sin 30° = 0,5. Lame rihm surub poole nõrgemalt — rihmu on vaja kaks korda rohkem.', 'Mida järsem rihm, seda tugevamini see surub.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'ru', 'Ремень через верх груза натянут под углом 30° вместо почти 90°. Что с прижимом?', '["Почти не меняется","Уменьшается примерно вдвое","Увеличивается","Уменьшается на 10%"]'::jsonb, 1, 'Прижим пропорционален синусу угла: sin 90° = 1, sin 30° = 0,5. Пологий ремень прижимает вдвое слабее — ремней понадобится вдвое больше.', 'Чем круче ремень, тем сильнее он прижимает.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'sv', 'Ett band över lasten är spänt i 30° i stället för nästan 90°. Vad händer med anpressningen?', '["Den ändras knappt","Den minskar ungefär till hälften","Den ökar","Den minskar med 10 %"]'::jsonb, 1, 'Anpressningen är proportionell mot vinkelns sinus: sin 90° = 1, sin 30° = 0,5. Ett flackt band pressar hälften så hårt — du behöver dubbelt så många band.', 'Ju brantare band, desto hårdare pressar det.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'lv', 'Siksna pāri kravai nospriegota 30° leņķī gandrīz 90° vietā. Kas notiek ar piespiedienu?', '["Gandrīz nemainās","Samazinās aptuveni uz pusi","Palielinās","Samazinās par 10%"]'::jsonb, 1, 'Piespiediens ir proporcionāls leņķa sinusam: sin 90° = 1, sin 30° = 0,5. Lēzena siksna piespiež divreiz vājāk — siksnu vajadzēs divreiz vairāk.', 'Jo stāvāka siksna, jo stiprāk tā piespiež.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'lt', 'Diržas per krovinio viršų įtemptas 30° kampu vietoj beveik 90°. Kas nutinka prispaudimui?', '["Beveik nesikeičia","Sumažėja maždaug perpus","Padidėja","Sumažėja 10 %"]'::jsonb, 1, 'Prispaudimas proporcingas kampo sinusui: sin 90° = 1, sin 30° = 0,5. Nuolaidus diržas prispaudžia dvigubai silpniau – diržų reikės dvigubai daugiau.', 'Kuo statesnis diržas, tuo stipriau jis prispaudžia.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'pl', 'Pas przez górę ładunku jest napięty pod kątem 30° zamiast prawie 90°. Co z dociskiem?', '["Prawie się nie zmienia","Zmniejsza się mniej więcej o połowę","Zwiększa się","Zmniejsza się o 10%"]'::jsonb, 1, 'Docisk jest proporcjonalny do sinusa kąta: sin 90° = 1, sin 30° = 0,5. Płaski pas dociska dwa razy słabiej – pasów potrzeba dwa razy więcej.', 'Im bardziej stromy pas, tym mocniej dociska.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'nb', 'En stroppe over lasten er strammet i 30° i stedet for nesten 90°. Hva skjer med nedpressingen?', '["Den endres knapt","Den blir omtrent halvert","Den øker","Den minker med 10 %"]'::jsonb, 1, 'Nedpressingen er proporsjonal med sinus til vinkelen: sin 90° = 1, sin 30° = 0,5. En flat stroppe presser halvparten så hardt — du trenger dobbelt så mange stropper.', 'Jo brattere stroppe, desto hardere presser den.', 'EN 12195-1'),
  ('cargo', 'cargo.g5', 'da', 'En strop over lasten er strammet i 30° i stedet for næsten 90°. Hvad sker der med nedpresningen?', '["Den ændrer sig næsten ikke","Den bliver cirka halveret","Den øges","Den falder med 10 %"]'::jsonb, 1, 'Nedpresningen er proportional med vinklens sinus: sin 90° = 1, sin 30° = 0,5. En flad strop presser halvt så hårdt — du skal bruge dobbelt så mange stropper.', 'Jo stejlere strop, desto hårdere presser den.', 'EN 12195-1'),
  ('cargo', 'cargo.g6', 'fi', 'Miksi kuorman alle laitetaan liukueste?', '["Ettei lattia naarmuunnu","Se lisää kitkaa, joten vöitä tarvitaan vähemmän","Se korvaa vyöt kokonaan","Iskunvaimennukseksi lastatessa"]'::jsonb, 1, 'Liukueste nostaa kitkakerrointa (esimerkiksi 0,45:stä 0,6:een). Kitka pitää itse osan voimasta, ja vöiden kuormitus pienenee.', 'Kumi pitää paremmin kuin puu.', 'EN 12195-1, liite B'),
  ('cargo', 'cargo.g6', 'en', 'Why put an anti-slip mat under the cargo?', '["So the floor doesn''t get scratched","It increases friction, so fewer straps are needed","It replaces straps completely","To cushion the cargo during loading"]'::jsonb, 1, 'The mat increases the friction coefficient (for example from 0.45 to 0.6). Friction itself holds part of the force, and the load on the straps drops.', 'Rubber grips better than wood.', 'EN 12195-1, Annex B'),
  ('cargo', 'cargo.g6', 'et', 'Miks panna koorma alla libisemisvastane matt?', '["Et põrand ei kriimustuks","See suurendab hõõrdumist ja rihmu on vaja vähem","See asendab rihmad täielikult","Löökide summutamiseks laadimisel"]'::jsonb, 1, 'Matt suurendab hõõrdetegurit (näiteks 0,45-lt 0,6-le). Hõõrdumine hoiab ise osa jõust kinni ja rihmade koormus väheneb.', 'Kumm haakub paremini kui puit.', 'EN 12195-1, lisa B'),
  ('cargo', 'cargo.g6', 'ru', 'Зачем класть антискользящий коврик под груз?', '["Чтобы не поцарапать пол","Он повышает трение, и ремней нужно меньше","Он заменяет ремни полностью","Для амортизации при погрузке"]'::jsonb, 1, 'Коврик повышает коэффициент трения (например, с 0,45 до 0,6). Трение само удерживает часть силы, и нагрузка на ремни падает.', 'Резина цепляется лучше дерева.', 'EN 12195-1, Приложение B'),
  ('cargo', 'cargo.g6', 'sv', 'Varför lägga en friktionsmatta under lasten?', '["Så att golvet inte repas","Den ökar friktionen, så det behövs färre band","Den ersätter banden helt","För att dämpa vid lastning"]'::jsonb, 1, 'Mattan höjer friktionstalet (till exempel från 0,45 till 0,6). Friktionen håller själv en del av kraften, och belastningen på banden minskar.', 'Gummi greppar bättre än trä.', 'EN 12195-1, bilaga B'),
  ('cargo', 'cargo.g6', 'lv', 'Kāpēc zem kravas liek pretslīdes paklāju?', '["Lai nesaskrāpētu grīdu","Tas palielina berzi, un siksnu vajag mazāk","Tas pilnībā aizstāj siksnas","Amortizācijai iekraušanas laikā"]'::jsonb, 1, 'Paklājs palielina berzes koeficientu (piemēram, no 0,45 līdz 0,6). Berze pati notur daļu spēka, un slodze uz siksnām samazinās.', 'Gumija ķeras labāk nekā koks.', 'EN 12195-1, pielikums B'),
  ('cargo', 'cargo.g6', 'lt', 'Kam po kroviniu dėti neslystantį kilimėlį?', '["Kad nesubraižytų grindų","Jis padidina trintį, ir diržų reikia mažiau","Jis visiškai pakeičia diržus","Amortizacijai kraunant"]'::jsonb, 1, 'Kilimėlis padidina trinties koeficientą (pvz., nuo 0,45 iki 0,6). Trintis pati sulaiko dalį jėgos, ir diržų apkrova sumažėja.', 'Guma sukimba geriau nei mediena.', 'EN 12195-1, priedas B'),
  ('cargo', 'cargo.g6', 'pl', 'Po co kłaść matę antypoślizgową pod ładunek?', '["Żeby nie porysować podłogi","Zwiększa tarcie, więc pasów potrzeba mniej","Całkowicie zastępuje pasy","Do amortyzacji przy załadunku"]'::jsonb, 1, 'Mata zwiększa współczynnik tarcia (np. z 0,45 do 0,6). Tarcie samo utrzymuje część siły i obciążenie pasów spada.', 'Guma trzyma lepiej niż drewno.', 'EN 12195-1, załącznik B'),
  ('cargo', 'cargo.g6', 'nb', 'Hvorfor legge en friksjonsmatte under lasten?', '["Så gulvet ikke blir ripete","Den øker friksjonen, så det trengs færre stropper","Den erstatter stroppene helt","For demping under lasting"]'::jsonb, 1, 'Matten øker friksjonskoeffisienten (for eksempel fra 0,45 til 0,6). Friksjonen holder selv en del av kraften, og belastningen på stroppene går ned.', 'Gummi griper bedre enn tre.', 'EN 12195-1, vedlegg B'),
  ('cargo', 'cargo.g6', 'da', 'Hvorfor lægge en friktionsmåtte under lasten?', '["Så gulvet ikke bliver ridset","Den øger friktionen, så der skal bruges færre stropper","Den erstatter stropperne helt","For at dæmpe under læsning"]'::jsonb, 1, 'Måtten øger friktionskoefficienten (for eksempel fra 0,45 til 0,6). Friktionen holder selv en del af kraften, og belastningen på stropperne falder.', 'Gummi griber bedre end træ.', 'EN 12195-1, bilag B'),
  ('cargo', 'cargo.g7', 'fi', 'Kuorman ja etulaidan väliin jäi 50 cm rako. Mitä haittaa siitä on?', '["Ei mitään, jos vyöt on","Jarrutuksessa kuorma saa vauhtia ja iskee laitaan, eikä laitaan tukeminen toimi","Vain se, että kuorma voi naarmuuntua","Akselipainojen jakauma muuttuu, ei muuta"]'::jsonb, 1, 'Rakoon pääsevä kuorma ehtii jarrutuksessa liikkua ja iskee laitaan suuremmalla voimalla. Rako poistetaan tai täytetään: tyhjillä lavoilla, täyteilmatyynyillä, tukipuilla.', 'Isku on voimakkaampi kuin tasainen paine.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'en', 'There is a 50 cm gap between the cargo and the headboard. Why is that bad?', '["It isn''t, if there are straps","When braking, the cargo gains speed and hits the headboard, and blocking doesn''t work","Only because the cargo may get scratched","It only affects the axle load distribution"]'::jsonb, 1, 'Cargo with a gap has time to move when braking and hits the headboard with greater force. The gap must be removed or filled: with empty pallets, airbags or bracing.', 'An impact is stronger than steady pressure.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'et', 'Koorma ja esiseina vahele jäi 50 cm vahe. Mis selles halba on?', '["Ei midagi, kui rihmad on","Pidurdamisel saab koorem hoogu ja lööb vastu seina ning seinaga blokeerimine ei tööta","Ainult see, et koorem võib kriimustuda","Muutub ainult teljekoormuste jaotus"]'::jsonb, 1, 'Vahega koorem jõuab pidurdamisel liikuda ja lööb vastu seina suurema jõuga. Vahe tuleb kaotada või täita: tühjade kaubaaluste, õhkpatjade või tugedega.', 'Löök on tugevam kui ühtlane surve.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'ru', 'Между грузом и передним бортом остался зазор 50 см. Чем это плохо?', '["Ничем, если есть ремни","При торможении груз разгоняется и бьёт в борт, а блокировка бортом не работает","Только тем, что груз может поцарапаться","Нарушается распределение по осям, и всё"]'::jsonb, 1, 'Груз с зазором при торможении успевает сдвинуться и ударяет в борт с большей силой. Зазор нужно убрать или заполнить: пустыми паллетами, воздушными подушками, распорками.', 'Удар сильнее, чем плавное давление.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'sv', 'Det finns en lucka på 50 cm mellan lasten och framstammen. Varför är det dåligt?', '["Det är det inte, om det finns band","Vid inbromsning får lasten fart och slår i framstammen, och blockeringen fungerar inte","Bara för att lasten kan repas","Det påverkar bara axellastfördelningen"]'::jsonb, 1, 'Last med lucka hinner röra sig vid inbromsning och slår i framstammen med större kraft. Luckan ska tas bort eller fyllas: med tomma pallar, luftkuddar eller stöttor.', 'En smäll är kraftigare än ett jämnt tryck.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'lv', 'Starp kravu un priekšējo bortu palika 50 cm sprauga. Kāpēc tas ir slikti?', '["Nekāpēc, ja ir siksnas","Bremzējot krava ieskrienas un triecas bortā, un bloķēšana ar bortu nedarbojas","Tikai tāpēc, ka krava var saskrāpēties","Mainās tikai slodzes sadalījums pa asīm"]'::jsonb, 1, 'Krava ar spraugu bremzējot paspēj pakustēties un triecas bortā ar lielāku spēku. Sprauga jānovērš vai jāaizpilda: ar tukšām paletēm, gaisa spilveniem, balstiem.', 'Trieciens ir spēcīgāks par vienmērīgu spiedienu.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'lt', 'Tarp krovinio ir priekinio borto liko 50 cm tarpas. Kuo tai blogai?', '["Niekuo, jei yra diržų","Stabdant krovinys įsibėgėja ir atsitrenkia į bortą, o blokavimas bortu neveikia","Tik tuo, kad krovinys gali būti subraižytas","Pasikeičia tik apkrovos pasiskirstymas ašims"]'::jsonb, 1, 'Krovinys su tarpu stabdant spėja pajudėti ir atsitrenkia į bortą didesne jėga. Tarpą reikia pašalinti arba užpildyti: tuščiais padėklais, oro pagalvėmis, atramomis.', 'Smūgis stipresnis nei tolygus spaudimas.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'pl', 'Między ładunkiem a przednią ścianą została szczelina 50 cm. Dlaczego to źle?', '["Nic złego, jeśli są pasy","Przy hamowaniu ładunek nabiera prędkości i uderza w ścianę, a blokada ścianą nie działa","Tylko dlatego, że ładunek może się porysować","Zmienia się tylko rozkład nacisku na osie"]'::jsonb, 1, 'Ładunek ze szczeliną przy hamowaniu zdąży się przesunąć i uderza w ścianę z większą siłą. Szczelinę trzeba usunąć lub wypełnić: pustymi paletami, poduszkami powietrznymi, rozporami.', 'Uderzenie jest silniejsze niż równomierny nacisk.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'nb', 'Det er en luke på 50 cm mellom lasten og frontveggen. Hvorfor er det dårlig?', '["Det er det ikke, hvis det er stropper","Ved bremsing får lasten fart og slår i frontveggen, og blokkeringen virker ikke","Bare fordi lasten kan bli ripete","Det påvirker bare akseltrykksfordelingen"]'::jsonb, 1, 'Last med luke rekker å bevege seg ved bremsing og slår i frontveggen med større kraft. Luken må fjernes eller fylles: med tomme paller, luftputer eller stag.', 'Et slag er kraftigere enn jevnt trykk.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g7', 'da', 'Der er et mellemrum på 50 cm mellem lasten og forsmækken. Hvorfor er det dårligt?', '["Det er det ikke, hvis der er stropper","Ved opbremsning får lasten fart og rammer forsmækken, og blokeringen virker ikke","Kun fordi lasten kan blive ridset","Det påvirker kun akseltryksfordelingen"]'::jsonb, 1, 'Last med mellemrum når at flytte sig ved opbremsning og rammer forsmækken med større kraft. Mellemrummet skal fjernes eller udfyldes: med tomme paller, luftpuder eller afstivning.', 'Et stød er kraftigere end et jævnt tryk.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g8', 'fi', 'Vyön etiketti on revennyt irti, mutta vyö näyttää hyvältä. Saako sitä käyttää?', '["Kyllä, jos siinä ei ole viiltoja","Kyllä, jos sen kiristää kovempaa","Ei, ilman etikettiä vyötä ei käytetä","Vain kevyelle kuormalle"]'::jsonb, 2, 'Vyö ilman etikettiä poistetaan käytöstä: sen LC ja STF eivät ole tiedossa. Sama koskee viiltoja saaneita vöitä ja vaurioituneita räikkiä.', 'Ilman merkintää ei tiedä, mitä vyö kestää.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'en', 'A strap''s label has been torn off, but it looks fine. Can you use it?', '["Yes, if there are no cuts","Yes, if you tension it harder","No, a strap without a label is not used","Only for light cargo"]'::jsonb, 2, 'A strap without a label is taken out of use: its LC and STF are unknown. The same applies to straps with cuts and damaged ratchets.', 'Without marking, you don''t know what the strap can hold.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'et', 'Rihma silt on ära rebitud, aga rihm näeb korras välja. Kas seda võib kasutada?', '["Jah, kui sisselõikeid pole","Jah, kui tugevamini pingutada","Ei, sildita rihma ei kasutata","Ainult kerge koorma jaoks"]'::jsonb, 2, 'Sildita rihm võetakse kasutusest välja: selle LC ja STF pole teada. Sama kehtib sisselõigetega rihmade ja kahjustatud põrkmehhanismide kohta.', 'Märgistuseta ei tea, mida rihm talub.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'ru', 'У ремня оторвана этикетка, но выглядит он нормально. Можно использовать?', '["Да, если нет порезов","Да, если натянуть сильнее","Нет, без этикетки ремень не используют","Только для лёгкого груза"]'::jsonb, 2, 'Ремень без этикетки выводят из работы: неизвестны его LC и STF. То же касается ремней с порезами и повреждённых храповиков.', 'Без маркировки неизвестно, что ремень выдержит.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'sv', 'Etiketten på ett spännband har slitits bort, men bandet ser bra ut. Får du använda det?', '["Ja, om det inte har några skåror","Ja, om du spänner hårdare","Nej, ett band utan etikett används inte","Bara för lätt last"]'::jsonb, 2, 'Ett band utan etikett tas ur bruk: dess LC och STF är okända. Detsamma gäller band med skåror och skadade spännare.', 'Utan märkning vet du inte vad bandet klarar.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'lv', 'Siksnai noplēsta etiķete, bet izskatās tā normāli. Vai to drīkst lietot?', '["Jā, ja nav iegriezumu","Jā, ja nospriego stiprāk","Nē, siksnu bez etiķetes nelieto","Tikai vieglai kravai"]'::jsonb, 2, 'Siksnu bez etiķetes izņem no lietošanas: tās LC un STF nav zināmi. Tas pats attiecas uz siksnām ar iegriezumiem un bojātiem sprūdratiem.', 'Bez marķējuma nav zināms, ko siksna izturēs.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'lt', 'Nuo diržo nuplėšta etiketė, bet jis atrodo gerai. Ar galima naudoti?', '["Taip, jei nėra įpjovimų","Taip, jei stipriau įtempsi","Ne, diržas be etiketės nenaudojamas","Tik lengvam kroviniui"]'::jsonb, 2, 'Diržas be etiketės išimamas iš naudojimo: nežinomi jo LC ir STF. Tas pats taikoma diržams su įpjovimais ir pažeistoms terkšlėms.', 'Be žymėjimo nežinoma, ką diržas atlaikys.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'pl', 'Pas ma oderwaną etykietę, ale wygląda normalnie. Można go używać?', '["Tak, jeśli nie ma nacięć","Tak, jeśli mocniej się go napnie","Nie, pasa bez etykiety się nie używa","Tylko do lekkiego ładunku"]'::jsonb, 2, 'Pas bez etykiety wycofuje się z użycia: nie są znane jego LC i STF. To samo dotyczy pasów z nacięciami i uszkodzonych grzechotek.', 'Bez oznakowania nie wiadomo, co pas wytrzyma.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'nb', 'Etiketten på en stroppe er revet av, men den ser fin ut. Kan du bruke den?', '["Ja, hvis den ikke har kutt","Ja, hvis du strammer hardere","Nei, en stroppe uten etikett brukes ikke","Bare til lett last"]'::jsonb, 2, 'En stroppe uten etikett tas ut av bruk: LC og STF er ukjent. Det samme gjelder stropper med kutt og skadde skraller.', 'Uten merking vet du ikke hva stroppen tåler.', 'EN 12195-2'),
  ('cargo', 'cargo.g8', 'da', 'Etiketten på en strop er revet af, men den ser fin ud. Må du bruge den?', '["Ja, hvis den ikke har snit","Ja, hvis du strammer hårdere","Nej, en strop uden etiket bruges ikke","Kun til let last"]'::jsonb, 2, 'En strop uden etiket tages ud af brug: dens LC og STF er ukendte. Det samme gælder stropper med snit og beskadigede skralder.', 'Uden mærkning ved du ikke, hvad stroppen kan holde.', 'EN 12195-2'),
  ('cargo', 'cargo.g9', 'fi', 'Mihin sidontavyön kulmasuojia tarvitaan?', '["Ulkonäön vuoksi","Ne suojaavat vyötä teräviltä reunoilta ja jakavat kiristyksen","Ettei vyö liu''u pressun päällä","Niitä käytetään vain ADR-kuljetuksissa"]'::jsonb, 1, 'Kulmasuojat suojaavat vyötä viilloilta ja auttavat kiristystä jakautumaan kuorman yli sen sijaan, että se jäisi yhdelle puolelle.', 'Terävä reuna leikkaa vyön.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'en', 'What are corner protectors under the strap for?', '["For looks","They protect the strap from sharp edges and spread the tension","So the strap doesn''t slide on the curtain","They are only used for ADR"]'::jsonb, 1, 'Corner protectors protect the strap from cuts and help the tension spread across the cargo instead of staying on one side.', 'A sharp edge cuts the strap.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'et', 'Milleks on vaja rihma nurgakaitsmeid?', '["Ilu pärast","Need kaitsevad rihma teravate servade eest ja jaotavad pinget","Et rihm ei libiseks tendil","Neid kasutatakse ainult ADR-veol"]'::jsonb, 1, 'Nurgakaitsmed kaitsevad rihma sisselõigete eest ja aitavad pingel jaotuda üle koorma, mitte jääda ühele küljele.', 'Terav serv lõikab rihma.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'ru', 'Зачем нужны защитные уголки под ремень?', '["Для красоты","Защищают ремень от острых кромок и распределяют натяжение","Чтобы ремень не скользил по тенту","Их используют только для ADR"]'::jsonb, 1, 'Уголки защищают ремень от порезов и помогают натяжению распределиться по грузу, а не остаться на одной стороне.', 'Острая кромка режет ремень.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'sv', 'Vad är kantskydd under bandet till för?', '["För utseendets skull","De skyddar bandet mot vassa kanter och fördelar spänningen","För att bandet inte ska glida på kapellet","De används bara för ADR"]'::jsonb, 1, 'Kantskydd skyddar bandet mot skärskador och hjälper spänningen att fördela sig över lasten i stället för att stanna på ena sidan.', 'En vass kant skär av bandet.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'lv', 'Kam vajadzīgi siksnas stūru aizsargi?', '["Skaistumam","Tie aizsargā siksnu no asām malām un sadala nospriegojumu","Lai siksna neslīdētu pa tentu","Tos lieto tikai ADR pārvadājumos"]'::jsonb, 1, 'Stūru aizsargi pasargā siksnu no iegriezumiem un palīdz nospriegojumam sadalīties pa kravu, nevis palikt vienā pusē.', 'Asa mala pārgriež siksnu.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'lt', 'Kam reikalingi apsauginiai kampai po diržu?', '["Dėl grožio","Jie saugo diržą nuo aštrių briaunų ir paskirsto įtempimą","Kad diržas neslystų tentu","Jie naudojami tik ADR"]'::jsonb, 1, 'Kampai apsaugo diržą nuo įpjovimų ir padeda įtempimui pasiskirstyti per krovinį, o ne likti vienoje pusėje.', 'Aštri briauna perpjauna diržą.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'pl', 'Po co są narożniki ochronne pod pasem?', '["Dla ozdoby","Chronią pas przed ostrymi krawędziami i rozkładają naciąg","Żeby pas nie ślizgał się po plandece","Używa się ich tylko w ADR"]'::jsonb, 1, 'Narożniki chronią pas przed przecięciem i pomagają rozłożyć naciąg na ładunek, zamiast zostawić go po jednej stronie.', 'Ostra krawędź przecina pas.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'nb', 'Hva er kantbeskyttere under stroppen til for?', '["For utseendets skyld","De beskytter stroppen mot skarpe kanter og fordeler strammingen","For at stroppen ikke skal gli på kapellet","De brukes bare ved ADR"]'::jsonb, 1, 'Kantbeskyttere beskytter stroppen mot kutt og hjelper strammingen å fordele seg over lasten i stedet for å bli på én side.', 'En skarp kant kutter stroppen.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g9', 'da', 'Hvad skal kantbeskyttere under stroppen bruges til?', '["For udseendets skyld","De beskytter stroppen mod skarpe kanter og fordeler stramningen","For at stroppen ikke glider på presenningen","De bruges kun ved ADR"]'::jsonb, 1, 'Kantbeskyttere beskytter stroppen mod snit og hjælper stramningen med at fordele sig over lasten i stedet for at blive på én side.', 'En skarp kant skærer stroppen over.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g10', 'fi', 'Pitävätkö verhopuoliperävaunun sivuverhot kuorman paikallaan?', '["Kyllä, aina","Yleensä eivät — vain jos kori on sertifioitu siihen ja kuorma on sijoitettu sertifikaatin mukaan","Kyllä, jos ne kiristetään tiukalle","Kyllä, alle 10 t kuormalle"]'::jsonb, 1, 'Tavalliset verhot suojaavat säältä, eivät sido kuormaa. Ne voi ottaa huomioon vain, jos kori on sertifioitu (EN 12642, XL-luokka) ja kuorma on sijoitettu sertifikaatin ehtojen mukaan.', 'Kangas ei ole laita.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'en', 'Do the side curtains of a curtainsider trailer hold the cargo?', '["Yes, always","Usually not — only if the body is certified for it and the cargo is placed according to the certificate","Yes, if tightened firmly","Yes, for cargo up to 10 t"]'::jsonb, 1, 'Ordinary curtains protect against the weather; they are not securing. They can only be counted if the body is certified (EN 12642, class XL) and the cargo is stowed according to the certificate.', 'Fabric is not a side wall.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'et', 'Kas tentpoolhaagise külgkardinad hoiavad koormat?', '["Jah, alati","Tavaliselt mitte — ainult siis, kui kere on selleks sertifitseeritud ja koorem paigutatud sertifikaadi järgi","Jah, kui need tugevasti pingutada","Jah, kuni 10 t koormale"]'::jsonb, 1, 'Tavalised kardinad on ilmastikukaitse, mitte kinnitus. Neid võib arvestada ainult siis, kui kere on sertifitseeritud (EN 12642, klass XL) ja koorem on paigutatud sertifikaadi tingimuste järgi.', 'Kangas ei ole külgsein.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'ru', 'Удерживают ли боковые шторы тентованного полуприцепа груз?', '["Да, всегда","Обычно нет — только если кузов сертифицирован для этого и груз размещён по сертификату","Да, если их туго затянуть","Да, для груза до 10 т"]'::jsonb, 1, 'Обычные шторы — защита от погоды, а не крепление. Учитывать их можно только если кузов сертифицирован (EN 12642, класс XL) и груз уложен по условиям сертификата.', 'Ткань — не борт.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'sv', 'Håller sidokapellen på en gardintrailer lasten?', '["Ja, alltid","Oftast inte — bara om karossen är certifierad för det och lasten placerad enligt certifikatet","Ja, om de spänns hårt","Ja, för last upp till 10 t"]'::jsonb, 1, 'Vanliga kapell skyddar mot väder, de säkrar inte lasten. De får räknas med bara om karossen är certifierad (EN 12642, klass XL) och lasten är placerad enligt certifikatets villkor.', 'Tyg är ingen sidolämm.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'lv', 'Vai tentētas puspiekabes sānu aizkari notur kravu?', '["Jā, vienmēr","Parasti nē — tikai tad, ja virsbūve tam sertificēta un krava izvietota atbilstoši sertifikātam","Jā, ja tos cieši savelk","Jā, kravai līdz 10 t"]'::jsonb, 1, 'Parastie aizkari ir aizsardzība pret laikapstākļiem, nevis nostiprinājums. Tos var ņemt vērā tikai tad, ja virsbūve ir sertificēta (EN 12642, XL klase) un krava izvietota saskaņā ar sertifikāta nosacījumiem.', 'Audums nav borts.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'lt', 'Ar tentinės puspriekabės šoninės užuolaidos išlaiko krovinį?', '["Taip, visada","Paprastai ne – tik jei kėbulas tam sertifikuotas ir krovinys išdėstytas pagal sertifikatą","Taip, jei jas stipriai įtempsi","Taip, kroviniui iki 10 t"]'::jsonb, 1, 'Įprastos užuolaidos – apsauga nuo oro sąlygų, o ne tvirtinimas. Jas galima įskaityti tik jei kėbulas sertifikuotas (EN 12642, XL klasė) ir krovinys sukrautas pagal sertifikato sąlygas.', 'Audinys – ne bortas.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'pl', 'Czy boczne kurtyny naczepy firanki utrzymują ładunek?', '["Tak, zawsze","Zwykle nie – tylko jeśli nadwozie ma do tego certyfikat, a ładunek jest ułożony zgodnie z nim","Tak, jeśli mocno się je napnie","Tak, dla ładunku do 10 t"]'::jsonb, 1, 'Zwykłe kurtyny chronią przed pogodą, a nie mocują ładunku. Można je uwzględnić tylko wtedy, gdy nadwozie ma certyfikat (EN 12642, klasa XL), a ładunek jest ułożony zgodnie z warunkami certyfikatu.', 'Tkanina to nie burta.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'nb', 'Holder sidegardinene på en gardinsemitrailer lasten?', '["Ja, alltid","Vanligvis ikke — bare hvis karosseriet er sertifisert for det og lasten plassert etter sertifikatet","Ja, hvis de strammes godt","Ja, for last opptil 10 t"]'::jsonb, 1, 'Vanlige gardiner beskytter mot vær, de sikrer ikke lasten. De kan bare regnes med hvis karosseriet er sertifisert (EN 12642, klasse XL) og lasten er plassert etter vilkårene i sertifikatet.', 'Stoff er ingen sidevegg.', 'EN 12642'),
  ('cargo', 'cargo.g10', 'da', 'Holder sidegardinerne på en gardintrailer lasten?', '["Ja, altid","Normalt ikke — kun hvis karrosseriet er certificeret til det, og lasten er placeret efter certifikatet","Ja, hvis de strammes godt","Ja, for last op til 10 t"]'::jsonb, 1, 'Almindelige gardiner beskytter mod vejret; de sikrer ikke lasten. De må kun medregnes, hvis karrosseriet er certificeret (EN 12642, klasse XL), og lasten er placeret efter certifikatets betingelser.', 'Stof er ikke en sidefjæl.', 'EN 12642'),
  ('cargo', 'cargo.g11', 'fi', 'Miksi kuorma kannattaa tukea eteenpäin etulaitaan eikä pitää sitä yliheittovöillä?', '["Se on nopeampaa","0,8 g:n voimaa vastaan yliheittovöitä tarvitaan hyvin paljon","Yliheittovyöt eivät pidä ollenkaan","Asiakas vaatii niin"]'::jsonb, 1, 'Yliheittovyö pitää vain kitkan avulla. Eteenpäin suuntautuvaa 0,8 g:tä vastaan niitä tarvitaan paljon. Etulaita ottaa voiman vastaan suoraan laidan lujuuden rajoissa.', 'Vertaa voimia eteen ja sivuille.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'en', 'Why is it better to block the cargo forward against the headboard than to hold it with top-over straps?', '["It''s faster","Against 0.8 g you would need very many top-over straps","Top-over straps don''t hold at all","The customer requires it"]'::jsonb, 1, 'A top-over strap holds only through friction. Against 0.8 g forward you need many of them. Blocking against the headboard takes this force directly, within the strength of the headboard.', 'Compare the forces forward and sideways.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'et', 'Miks on parem koormat ettesuunas blokeerida esiseinaga kui hoida seda ülevalt üle rihmadega?', '["Nii on kiirem","0,8 g vastu on ülevalt üle rihmu vaja väga palju","Ülevalt üle rihmad ei hoia üldse","Nii nõuab klient"]'::jsonb, 1, 'Ülevalt üle rihm hoiab ainult hõõrdumise abil. Ettesuunas 0,8 g vastu on neid vaja palju. Esiseinaga blokeerimine võtab selle jõu vastu otse, seina tugevuse piires.', 'Võrdle jõude ette ja külgedele.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'ru', 'Почему груз вперёд лучше блокировать передним бортом, чем держать ремнями через верх?', '["Так быстрее","Против силы 0,8 g ремней через верх нужно очень много","Ремни через верх вообще не держат","Так требует заказчик"]'::jsonb, 1, 'Ремень через верх держит только за счёт трения. Против 0,8 g вперёд таких ремней нужно много. Блокировка бортом принимает эту силу напрямую, в пределах прочности борта.', 'Сравни силы вперёд и вбок.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'sv', 'Varför är det bättre att blockera lasten framåt mot framstammen än att hålla den med överfallsband?', '["Det går snabbare","Mot 0,8 g behövs väldigt många överfallsband","Överfallsband håller inte alls","Kunden kräver det"]'::jsonb, 1, 'Ett överfallsband håller bara genom friktion. Mot 0,8 g framåt behövs många sådana band. Blockering mot framstammen tar upp kraften direkt, inom framstammens hållfasthet.', 'Jämför krafterna framåt och i sidled.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'lv', 'Kāpēc kravu uz priekšu labāk bloķēt ar priekšējo bortu, nevis turēt ar siksnām pāri augšai?', '["Tā ir ātrāk","Pret 0,8 g spēku siksnu pāri augšai vajag ļoti daudz","Siksnas pāri augšai vispār netur","Tā prasa klients"]'::jsonb, 1, 'Siksna pāri augšai tur tikai ar berzi. Pret 0,8 g uz priekšu tādu siksnu vajag daudz. Bloķēšana ar bortu uzņem šo spēku tieši, borta izturības robežās.', 'Salīdzini spēkus uz priekšu un uz sāniem.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'lt', 'Kodėl krovinį į priekį geriau blokuoti priekiniu bortu, nei laikyti diržais per viršų?', '["Taip greičiau","Prieš 0,8 g jėgą diržų per viršų reikia labai daug","Diržai per viršų visai nelaiko","Taip reikalauja užsakovas"]'::jsonb, 1, 'Diržas per viršų laiko tik trinties dėka. Prieš 0,8 g į priekį tokių diržų reikia daug. Blokavimas bortu šią jėgą priima tiesiogiai, borto stiprumo ribose.', 'Palygink jėgas į priekį ir į šonus.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'pl', 'Dlaczego ładunek do przodu lepiej zablokować przednią ścianą, niż trzymać pasami przez górę?', '["Tak jest szybciej","Przeciw sile 0,8 g pasów przez górę potrzeba bardzo dużo","Pasy przez górę w ogóle nie trzymają","Tak wymaga zleceniodawca"]'::jsonb, 1, 'Pas przez górę trzyma tylko dzięki tarciu. Przeciw 0,8 g do przodu takich pasów potrzeba wiele. Blokada ścianą przejmuje tę siłę bezpośrednio, w granicach wytrzymałości ściany.', 'Porównaj siły do przodu i na boki.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'nb', 'Hvorfor er det bedre å blokkere lasten forover mot frontveggen enn å holde den med overfallsstropper?', '["Det går raskere","Mot 0,8 g trengs det svært mange overfallsstropper","Overfallsstropper holder ikke i det hele tatt","Kunden krever det"]'::jsonb, 1, 'En overfallsstroppe holder bare gjennom friksjon. Mot 0,8 g forover trengs mange slike. Blokkering mot frontveggen tar opp kraften direkte, innenfor frontveggens styrke.', 'Sammenlign kreftene forover og sideveis.', 'EN 12195-1'),
  ('cargo', 'cargo.g11', 'da', 'Hvorfor er det bedre at blokere lasten fremad mod forsmækken end at holde den med overfaldsstropper?', '["Det går hurtigere","Mod 0,8 g skal der bruges rigtig mange overfaldsstropper","Overfaldsstropper holder slet ikke","Kunden kræver det"]'::jsonb, 1, 'En overfaldsstrop holder kun via friktion. Mod 0,8 g fremad skal der mange af dem til. Blokering mod forsmækken optager kraften direkte inden for forsmækkens styrke.', 'Sammenlign kræfterne fremad og til siden.', 'EN 12195-1'),
  ('cargo', 'cargo.g12', 'fi', 'Varasto lastasi, kuljettaja ei osallistunut. Kuka vastaa sidonnasta matkan aikana?', '["Vain varasto","Vain asiakas","Myös kuljettajan on tarkistettava sidonta ennen lähtöä","Ei kukaan, jos on CMR"]'::jsonb, 2, 'Kuljettaja vastaa ajoneuvonsa ja kuormansa turvallisuudesta tiellä. Vaikka lastaajana olisi joku muu, hänen on tarkistettava sidonta ennen lähtöä ja matkan aikana.', 'Tarkastuksessa kysytään kuljettajalta.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'en', 'The warehouse loaded, the driver wasn''t involved. Who is responsible for securing on the road?', '["Only the warehouse","Only the customer","The driver must also check the securing before departure","No one, if there is a CMR"]'::jsonb, 2, 'The driver is responsible for the safety of their vehicle and load on the road. Even if others loaded it, the driver must check the securing before departure and during the trip.', 'At a roadside check, they will ask the driver.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'et', 'Laadis ladu, juht ei osalenud. Kes vastutab kinnituse eest teel?', '["Ainult ladu","Ainult klient","Ka juht peab kinnitust enne väljasõitu kontrollima","Mitte keegi, kui on CMR"]'::jsonb, 2, 'Juht vastutab oma sõiduki ja koorma ohutuse eest teel. Isegi kui laadisid teised, peab ta kinnitust enne väljasõitu ja teel kontrollima.', 'Kontrollis küsitakse juhilt.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'ru', 'Грузил склад, водитель не участвовал. Кто отвечает за крепление в пути?', '["Только склад","Только заказчик","Водитель тоже обязан проверить крепление перед выездом","Никто, если есть CMR"]'::jsonb, 2, 'Водитель отвечает за безопасность своего транспортного средства и груза на дороге. Даже если грузили другие, он должен проверить крепление перед выездом и в пути.', 'На проверке спросят с водителя.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'sv', 'Lagret lastade, föraren var inte med. Vem ansvarar för lastsäkringen på vägen?', '["Bara lagret","Bara kunden","Även föraren måste kontrollera säkringen före avfärd","Ingen, om det finns en CMR"]'::jsonb, 2, 'Föraren ansvarar för att fordonet och lasten är säkra på vägen. Även om andra lastade måste föraren kontrollera säkringen före avfärd och under resan.', 'Vid en kontroll frågar man föraren.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'lv', 'Iekrāva noliktava, vadītājs nepiedalījās. Kas atbild par nostiprinājumu ceļā?', '["Tikai noliktava","Tikai klients","Arī vadītājam jāpārbauda nostiprinājums pirms izbraukšanas","Neviens, ja ir CMR"]'::jsonb, 2, 'Vadītājs atbild par sava transportlīdzekļa un kravas drošību uz ceļa. Pat ja iekrāva citi, viņam jāpārbauda nostiprinājums pirms izbraukšanas un ceļā.', 'Pārbaudē prasīs no vadītāja.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'lt', 'Krovė sandėlis, vairuotojas nedalyvavo. Kas atsako už tvirtinimą kelyje?', '["Tik sandėlis","Tik užsakovas","Vairuotojas taip pat privalo patikrinti tvirtinimą prieš išvykdamas","Niekas, jei yra CMR"]'::jsonb, 2, 'Vairuotojas atsako už savo transporto priemonės ir krovinio saugumą kelyje. Net jei krovė kiti, jis turi patikrinti tvirtinimą prieš išvykdamas ir kelionės metu.', 'Patikrinimo metu klaus vairuotojo.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'pl', 'Ładował magazyn, kierowca nie brał udziału. Kto odpowiada za mocowanie w trasie?', '["Tylko magazyn","Tylko zleceniodawca","Kierowca również musi sprawdzić mocowanie przed wyjazdem","Nikt, jeśli jest CMR"]'::jsonb, 2, 'Kierowca odpowiada za bezpieczeństwo swojego pojazdu i ładunku na drodze. Nawet jeśli ładowali inni, musi sprawdzić mocowanie przed wyjazdem i w trasie.', 'Podczas kontroli zapytają kierowcę.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'nb', 'Lageret lastet, sjåføren var ikke med. Hvem har ansvaret for sikringen på veien?', '["Bare lageret","Bare kunden","Også sjåføren må kontrollere sikringen før avreise","Ingen, hvis det finnes en CMR"]'::jsonb, 2, 'Sjåføren har ansvar for at kjøretøyet og lasten er sikre på veien. Selv om andre lastet, må sjåføren kontrollere sikringen før avreise og underveis.', 'I en kontroll spør de sjåføren.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g12', 'da', 'Lageret læssede, chaufføren var ikke med. Hvem har ansvaret for sikringen på vejen?', '["Kun lageret","Kun kunden","Chaufføren skal også kontrollere sikringen før afgang","Ingen, hvis der er en CMR"]'::jsonb, 2, 'Chaufføren har ansvaret for, at køretøjet og lasten er sikre på vejen. Selv om andre har læsset, skal chaufføren kontrollere sikringen før afgang og undervejs.', 'Ved en kontrol spørger de chaufføren.', 'Tieliikennelaki 729/2018'),
  ('cargo', 'cargo.g13', 'fi', 'Vyön STF on 400 daN. Se on suunnilleen…', '["40 kg:n voima","400 kg:n voima","4 000 kg:n voima","40 000 kg:n voima"]'::jsonb, 1, '1 daN (dekanewton) ≈ 1 kg:n voima. STF 400 daN on noin 400 kg kiristystä.', 'daN on lähes sama kuin kilogramma.', 'SI'),
  ('cargo', 'cargo.g13', 'en', 'A strap has STF 400 daN. That is roughly…', '["40 kg of force","400 kg of force","4,000 kg of force","40,000 kg of force"]'::jsonb, 1, '1 daN (decanewton) ≈ 1 kg of force. STF 400 daN is about 400 kg of tension.', 'A daN is almost a kilogram.', 'SI'),
  ('cargo', 'cargo.g13', 'et', 'Rihma STF on 400 daN. See on umbes…', '["40 kg jõudu","400 kg jõudu","4000 kg jõudu","40 000 kg jõudu"]'::jsonb, 1, '1 daN (dekanjuuton) ≈ 1 kg jõudu. STF 400 daN on umbes 400 kg pingutust.', 'daN on peaaegu sama mis kilogramm.', 'SI'),
  ('cargo', 'cargo.g13', 'ru', 'Ремень STF 400 daN. Это примерно…', '["40 кг силы","400 кг силы","4 000 кг силы","40 000 кг силы"]'::jsonb, 1, '1 daN (декаНьютон) ≈ 1 кг силы. STF 400 daN — примерно 400 кг натяжения.', 'daN почти равен килограмму.', 'Единицы СИ'),
  ('cargo', 'cargo.g13', 'sv', 'Ett band har STF 400 daN. Det är ungefär…', '["40 kg kraft","400 kg kraft","4 000 kg kraft","40 000 kg kraft"]'::jsonb, 1, '1 daN (dekanewton) ≈ 1 kg kraft. STF 400 daN är ungefär 400 kg spänning.', 'En daN är nästan ett kilogram.', 'SI'),
  ('cargo', 'cargo.g13', 'lv', 'Siksnas STF ir 400 daN. Tas ir aptuveni…', '["40 kg spēka","400 kg spēka","4000 kg spēka","40 000 kg spēka"]'::jsonb, 1, '1 daN (dekaņūtons) ≈ 1 kg spēka. STF 400 daN — aptuveni 400 kg nospriegojuma.', 'daN ir gandrīz kilograms.', 'SI'),
  ('cargo', 'cargo.g13', 'lt', 'Diržo STF – 400 daN. Tai maždaug…', '["40 kg jėgos","400 kg jėgos","4000 kg jėgos","40 000 kg jėgos"]'::jsonb, 1, '1 daN (dekaniutonas) ≈ 1 kg jėgos. STF 400 daN – maždaug 400 kg įtempimo.', 'daN beveik lygus kilogramui.', 'SI'),
  ('cargo', 'cargo.g13', 'pl', 'Pas ma STF 400 daN. To mniej więcej…', '["40 kg siły","400 kg siły","4000 kg siły","40 000 kg siły"]'::jsonb, 1, '1 daN (dekaniuton) ≈ 1 kg siły. STF 400 daN to około 400 kg naciągu.', 'daN to prawie kilogram.', 'SI'),
  ('cargo', 'cargo.g13', 'nb', 'En stroppe har STF 400 daN. Det er omtrent…', '["40 kg kraft","400 kg kraft","4000 kg kraft","40 000 kg kraft"]'::jsonb, 1, '1 daN (dekanewton) ≈ 1 kg kraft. STF 400 daN er omtrent 400 kg stramming.', 'En daN er nesten et kilo.', 'SI'),
  ('cargo', 'cargo.g13', 'da', 'En strop har STF 400 daN. Det er cirka…', '["40 kg kraft","400 kg kraft","4000 kg kraft","40.000 kg kraft"]'::jsonb, 1, '1 daN (dekanewton) ≈ 1 kg kraft. STF 400 daN er cirka 400 kg stramning.', 'En daN er næsten et kilo.', 'SI'),
  ('cargo', 'cargo.g14', 'fi', 'Miten raskas ja kevyt kuorma sijoitetaan oikein?', '["Raskas päälle painamaan","Raskas alas ja keskelle akselipainot huomioiden","Miten on helpointa lastata","Raskas perävaunun takapäähän"]'::jsonb, 1, 'Raskas alas ja lähelle pituusakselia, jotta painopiste on matalalla eivätkä akselipainot ylitä sallittua.', 'Matala painopiste — vakaus.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'en', 'How should heavy and light cargo be placed?', '["Heavy on top to press down","Heavy at the bottom and in the centre, considering axle loads","However is easiest to load","Heavy at the very rear of the trailer"]'::jsonb, 1, 'Heavy items go low and close to the longitudinal axis, so the centre of gravity is low and axle loads stay within limits.', 'Low centre of gravity — stability.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'et', 'Kuidas paigutada rasket ja kerget koormat õigesti?', '["Raske peale, et suruks","Raske alla ja keskele, arvestades teljekoormust","Nii, kuidas on mugavam laadida","Raske haagise kõige tagumisse otsa"]'::jsonb, 1, 'Raske — alla ja pikitelje lähedale, et raskuskese oleks madalal ja teljekoormused ei ületaks lubatut.', 'Madal raskuskese — stabiilsus.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'ru', 'Как правильно разместить тяжёлый и лёгкий груз?', '["Тяжёлый наверх, чтобы прижимал","Тяжёлый вниз и по центру, с учётом нагрузки на оси","Как удобнее грузить","Тяжёлый в самый конец прицепа"]'::jsonb, 1, 'Тяжёлое — вниз и ближе к продольной оси, чтобы центр тяжести был низко и нагрузка на оси не превышала допустимую.', 'Низкий центр тяжести — устойчивость.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'sv', 'Hur placerar man tung och lätt last rätt?', '["Tungt överst så att det pressar","Tungt nederst och i mitten, med hänsyn till axeltrycket","Så som det är enklast att lasta","Tungt längst bak i trailern"]'::jsonb, 1, 'Tungt gods placeras lågt och nära längdaxeln, så att tyngdpunkten blir låg och axeltrycken inte överskrider det tillåtna.', 'Låg tyngdpunkt — stabilitet.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'lv', 'Kā pareizi izvietot smagu un vieglu kravu?', '["Smago augšā, lai piespiež","Smago apakšā un centrā, ņemot vērā slodzi uz asīm","Kā ērtāk iekraut","Smago pašā piekabes galā"]'::jsonb, 1, 'Smagais — lejā un tuvāk garenasij, lai smaguma centrs būtu zemu un slodze uz asīm nepārsniegtu pieļaujamo.', 'Zems smaguma centrs — stabilitāte.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'lt', 'Kaip teisingai išdėstyti sunkų ir lengvą krovinį?', '["Sunkų viršuje, kad prispaustų","Sunkų apačioje ir centre, atsižvelgiant į ašių apkrovą","Kaip patogiau krauti","Sunkų pačiame priekabos gale"]'::jsonb, 1, 'Sunkus – apačioje ir arčiau išilginės ašies, kad svorio centras būtų žemai ir ašių apkrova neviršytų leistinos.', 'Žemas svorio centras – stabilumas.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'pl', 'Jak prawidłowo rozmieścić ciężki i lekki ładunek?', '["Ciężki na górze, żeby dociskał","Ciężki na dole i pośrodku, z uwzględnieniem nacisku na osie","Tak, jak wygodniej ładować","Ciężki na samym końcu naczepy"]'::jsonb, 1, 'Ciężkie – na dół i bliżej osi podłużnej, aby środek ciężkości był nisko, a nacisk na osie nie przekraczał dopuszczalnego.', 'Niski środek ciężkości – stabilność.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'nb', 'Hvordan plasserer man tung og lett last riktig?', '["Tungt øverst så det presser","Tungt nederst og i midten, med tanke på akseltrykket","Slik det er enklest å laste","Tungt helt bakerst i traileren"]'::jsonb, 1, 'Tungt gods plasseres lavt og nær lengdeaksen, slik at tyngdepunktet blir lavt og akseltrykket ikke overskrider det tillatte.', 'Lavt tyngdepunkt — stabilitet.', 'EU Best Practice Guidelines on Cargo Securing'),
  ('cargo', 'cargo.g14', 'da', 'Hvordan placerer man tung og let last rigtigt?', '["Tungt øverst, så det presser","Tungt nederst og i midten under hensyn til akseltrykket","Sådan som det er nemmest at læsse","Tungt helt bagerst i traileren"]'::jsonb, 1, 'Tungt gods placeres lavt og tæt på længdeaksen, så tyngdepunktet bliver lavt, og akseltrykket ikke overstiger det tilladte.', 'Lavt tyngdepunkt — stabilitet.', 'EU Best Practice Guidelines on Cargo Securing')
